/**
 * Contact trigger. Contains no queries or DML; all logic lives in ContactTriggerHandler.
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {
    if (Trigger.isBefore) {
        ContactTriggerHandler.applyAccountDefaults(Trigger.new, Trigger.isInsert);
    } else if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.populateAccountPhones(Trigger.new);
    }
}
