```apex
/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Runs "without sharing" on purpose: the original logic lived directly in the trigger,
 * which runs in system context. Adding sharing enforcement here would change behaviour,
 * for example for contacts whose account the running user cannot see or edit.
 *
 * Limits per trigger invocation (up to 200 records):
 *   before insert / before update : 1 SOQL, 0 DML
 *   after insert                  : 1 SOQL, at most 1 DML
 */
public without sharing class ContactTriggerHandler {

    /**
     * Before insert / before update:
     * - a blank MailingCountry is defaulted from Account.BillingCountry
     * - on insert only, a blank LeadSource is defaulted from Account.AccountSource
     */
    public static void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: if an account has no phone, it takes the phone of the first new
     * contact (in trigger order) of that account that has a phone.
     */
    public static void populateAccountPhones(List<Contact> contacts) {
        // First contact phone per account, in trigger order.
        Map<Id, String> firstPhoneByAccountId = new Map<Id, String>();
        List<Id> accountIdsInOrder = new List<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null
                    && String.isNotBlank(c.Phone)
                    && !firstPhoneByAccountId.containsKey(c.AccountId)) {
                firstPhoneByAccountId.put(c.AccountId, c.Phone);
                accountIdsInOrder.add(c.AccountId);
            }
        }
        if (firstPhoneByAccountId.isEmpty()) {
            return;
        }

        Set<Id> accountIds = firstPhoneByAccountId.keySet();
        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIdsInOrder) {
            Account a = accountsById.get(accountId);
            if (a != null && String.isBlank(a.Phone)) {
                accountsToUpdate.add(new Account(
                    Id = accountId,
                    Phone = firstPhoneByAccountId.get(accountId)
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
