File: force-app/main/default/classes/ExchangeRateClient.cls
```apex
/**
 * Client for the FX rates provider, called through the Named Credential FB_Exchange_Rates.
 *
 * Usage:
 *   Map<String, Decimal> rates = ExchangeRateClient.getRates('EUR', new Set<String>{ 'USD', 'GBP' });
 */
public with sharing class ExchangeRateClient {

    @TestVisible
    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');
    private static final Integer TIMEOUT_MS = 20000;
    private static final Integer STATUS_OK = 200;
    private static final Integer STATUS_SERVICE_UNAVAILABLE = 503;

    public class ExchangeRateException extends Exception {}

    /**
     * Returns the rate for every requested quote currency against the base currency.
     * Codes are trimmed and upper-cased. Invalid input throws before any callout is made.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- Validate and normalise input (no callout before this passes) ----
        String base = normalise(baseCurrency);
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }
        Set<String> quotes = new Set<String>();
        for (String code : quoteCurrencies) {
            quotes.add(normalise(code));
        }

        List<String> sortedQuotes = new List<String>(quotes);
        sortedQuotes.sort();

        // ---- Build the request ----
        // Codes are validated to be exactly [A-Z]{3}, so they need no URL encoding.
        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT + '?base=' + base + '&symbols=' + String.join(sortedQuotes, ','));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        req.setTimeout(TIMEOUT_MS);

        // ---- Send, retrying once on 503 ----
        HttpResponse res = send(req);
        if (res.getStatusCode() == STATUS_SERVICE_UNAVAILABLE) {
            res = send(req);
        }

        Integer status = res.getStatusCode();
        if (status != STATUS_OK) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + status + '.'
            );
        }

        return parseRates(res.getBody(), quotes);
    }

    private static HttpResponse send(HttpRequest req) {
        try {
            return new Http().send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage(), e);
        }
    }

    private static String normalise(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (!CURRENCY_PATTERN.matcher(normalised).matches()) {
            throw new ExchangeRateException('Invalid currency code: "' + code + '".');
        }
        return normalised;
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> requested) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Exchange rate response body is empty.');
        }

        Map<String, Object> rates;
        try {
            Object parsed = JSON.deserializeUntyped(body);
            if (!(parsed instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Exchange rate response is not a JSON object.');
            }
            Object ratesObj = ((Map<String, Object>) parsed).get('rates');
            if (!(ratesObj instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Exchange rate response contains no "rates" object.');
            }
            rates = (Map<String, Object>) ratesObj;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Could not parse exchange rate response: ' + e.getMessage(), e);
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : requested) {
            Decimal rate = toDecimal(rates.get(code));
            if (rate == null) {
                throw new ExchangeRateException('No exchange rate returned for currency ' + code + '.');
            }
            result.put(code, rate);
        }
        return result;
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf(String.valueOf((Double) value));
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf(((String) value).trim());
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value: "' + value + '".', e);
            }
        }
        throw new ExchangeRateException('Invalid rate value type in exchange rate response.');
    }
}
```

**Design notes:**
- **Validation before any callout.** Every code is checked against `^[A-Z]{3}$` after it is trimmed and upper-cased. Null codes and a null or empty quote set throw before any request is built.
- **Duplicates collapse.** Inputs such as `' usd'` and `'USD'` normalise to the same value, so they become one entry.
- **Endpoint encoding.** The codes are already restricted to A–Z, so the endpoint uses literal commas in `symbols` and needs no URL encoding. The quote codes are sorted so the request is deterministic.
- **Retry.** The same `HttpRequest` is sent a second time only on a 503. Any other non-200 status throws immediately. The error message contains the numeric status code.
- **Callout failures.** A `CalloutException` (for example a timeout) is wrapped in `ExchangeRateException`.
- **Parsing.** Extra rates in the response are ignored. A missing rate, a missing `rates` object, an empty body or malformed JSON throws `ExchangeRateException`. Integer, double and numeric-string rate values are converted to `Decimal`.

The class runs `with sharing` and queries `WITH USER_MODE`, so it respects record sharing plus object and field permissions. It uses one SOQL query no matter how many accounts are passed in.

