/**
 * Service for grouping Contacts by the domain part of their email address.
 * Runs with sharing and queries in user mode, so the running user's record sharing,
 * object permissions and field-level security are respected.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the contacts of the given accounts grouped by lower-cased email domain
     * (e.g. Jane@Example.COM -> 'example.com'). Contacts without an email are skipped.
     *
     * @param accountIds Ids of the accounts whose contacts should be grouped
     * @return map of lower-cased email domain to the contacts with that domain;
     *         an empty map for a null or empty input
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Defensive copy without a null element; the caller's set is not modified
        Set<Id> ids = new Set<Id>(accountIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact c : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :ids
              AND Email != null
            WITH USER_MODE
            ORDER BY AccountId, Id
        ]) {
            String domain = extractDomain(c.Email);
            if (String.isBlank(domain)) {
                continue;
            }
            List<Contact> bucket = contactsByDomain.get(domain);
            if (bucket == null) {
                bucket = new List<Contact>();
                contactsByDomain.put(domain, bucket);
            }
            bucket.add(c);
        }

        return contactsByDomain;
    }

    /**
     * Extracts the lower-cased domain part (everything after the last '@') of an email.
     * Returns null when no usable domain can be derived.
     */
    private static String extractDomain(String email) {
        if (String.isBlank(email) || !email.contains('@')) {
            return null;
        }
        String domain = email.substringAfterLast('@').trim();
        return String.isBlank(domain) ? null : domain.toLowerCase();
    }
}
```

**Design notes:**
- **Sharing and security:** if the user has no access to `Contact` or `Contact.Email`, the method throws a `QueryException` rather than leaking data.
- **Null and empty input:** a null or empty set returns an empty map. Null Ids inside the set are dropped from a copy, so the caller's set is never changed.
- **Domain extraction:** the key is the text after the last `@`, trimmed and lower-cased (`Jane@Example.COM` → `example.com`).
- **Skipped contacts:** contacts with no email are left out by the `WHERE` clause. Contacts with an email that yields no domain are also skipped.
- **Fields:** each returned contact has `Id`, `Email` and `AccountId` populated.
- **Heap usage:** the SOQL for-loop processes rows in chunks, which keeps heap usage low on large data sets.

