/**
 * Generic record search used by the admin "record finder" Lightning component.
 *
 * Security model:
 *  - Object and field names are never concatenated from user input. Every name is resolved
 *    through Schema describe and the canonical API name returned by describe is used to build
 *    the query.
 *  - Filter values are never concatenated into the query. They are passed as bind variables
 *    through Database.queryWithBinds, so values cannot inject SOQL.
 *  - The query runs in AccessLevel.USER_MODE, which enforces the running user's sharing, CRUD
 *    and field-level security. Explicit describe checks are also done first so callers get a
 *    clear SearchException instead of a platform exception.
 *  - Every failure is reported as RecordSearchService.SearchException.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return doSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Turn any platform exception (QueryException, TypeException, ...) into the
            // documented exception type.
            throw new SearchException('Record search failed: ' + e.getMessage(), e);
        }
    }

    private static List<SObject> doSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Row limit
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        // Object (the global describe map is case-insensitive)
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName);
        if (sObjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
        String objectName = objDescribe.getName();
        if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
            throw new SearchException('You do not have access to object ' + objectName + '.');
        }

        // The describe field map is case-insensitive
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // SELECT list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        List<String> selectList = new List<String>{ 'Id' };
        Set<String> selectedLower = new Set<String>{ 'id' };
        for (String requested : fields) {
            Schema.DescribeFieldResult dfr = resolveField(fieldMap, requested, objectName);
            String canonical = dfr.getName();
            // Skip duplicates such as 'Name' and 'name', or an explicit 'Id'
            if (selectedLower.add(canonical.toLowerCase())) {
                selectList.add(canonical);
            }
        }

        String soql = 'SELECT ' + String.join(selectList, ', ') + ' FROM ' + objectName;

        // WHERE clause: one equality condition per filter, values bound
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            Integer i = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult dfr = resolveField(fieldMap, key, objectName);
                if (!dfr.isFilterable()) {
                    throw new SearchException(
                        'Field ' + dfr.getName() + ' cannot be used as a filter.'
                    );
                }
                // Bind names are generated by this class and never come from user input
                String bindName = 'filterValue' + i;
                binds.put(bindName, coerceValue(filters.get(key), dfr));
                conditions.add(dfr.getName() + ' = :' + bindName);
                i++;
            }
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }

        // ORDER BY
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult dfr = resolveField(fieldMap, orderByField, objectName);
            if (!dfr.isSortable()) {
                throw new SearchException('Field ' + dfr.getName() + ' cannot be sorted.');
            }
            soql += ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // LIMIT (validated Integer, also bound)
        binds.put('maxRowsLimit', maxRows);
        soql += ' LIMIT :maxRowsLimit';

        return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
    }

    /**
     * Resolves a field name case-insensitively and checks the user can read it.
     */
    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String objectName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A blank field name was supplied for ' + objectName + '.');
        }
        Schema.SObjectField token = fieldMap.get(fieldName);
        if (token == null) {
            throw new SearchException(
                'Field ' + fieldName + ' does not exist on ' + objectName + '.'
            );
        }
        Schema.DescribeFieldResult dfr = token.getDescribe();
        if (!dfr.isAccessible()) {
            throw new SearchException(
                'You do not have access to field ' + dfr.getName() + ' on ' + objectName + '.'
            );
        }
        return dfr;
    }

    /**
     * Checks a filter value is a supported scalar type. String values from the UI are
     * converted to the field's data type when that type is not text.
     */
    private static Object coerceValue(Object value, Schema.DescribeFieldResult dfr) {
        if (value == null) {
            return null;
        }
        if (value instanceof Id) {
            return value;
        }
        if (value instanceof String) {
            return coerceString((String) value, dfr);
        }
        if (value instanceof Boolean || value instanceof Date || value instanceof Datetime
            || value instanceof Time || value instanceof Decimal || value instanceof Integer
            || value instanceof Long || value instanceof Double) {
            return value;
        }
        throw new SearchException(
            'Unsupported filter value type for field ' + dfr.getName() + '.'
        );
    }

    private static Object coerceString(String s, Schema.DescribeFieldResult dfr) {
        String fieldName = dfr.getName();
        try {
            switch on dfr.getType() {
                when BOOLEAN {
                    String normalized = s.trim().toLowerCase();
                    if (normalized == 'true') {
                        return true;
                    }
                    if (normalized == 'false') {
                        return false;
                    }
                    throw new SearchException(
                        'Invalid Boolean value for field ' + fieldName + '.'
                    );
                }
                when DATE {
                    return Date.valueOf(s.trim());
                }
                when DATETIME {
                    return (Datetime) JSON.deserialize(
                        JSON.serialize(s.trim()), Datetime.class
                    );
                }
                when INTEGER {
                    return Integer.valueOf(s.trim());
                }
                when LONG {
                    return Long.valueOf(s.trim());
                }
                when DOUBLE, CURRENCY, PERCENT {
                    return Decimal.valueOf(s.trim());
                }
                when else {
                    // Text, picklist, reference/Id, email, phone, URL and similar types:
                    // bind the string as is.
                    return s;
                }
            }
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(
                'Invalid filter value for field ' + fieldName + ': ' + e.getMessage(), e
            );
        }
    }
}
```

**Injection safety**
- Object and field names are looked up through `Schema` describe, which matches names case-insensitively.
- Only the exact API names that describe returns are put into the query text.
- Every filter value and the row limit are passed as bind variables through `Database.queryWithBinds`. The bind names are generated by the class, not taken from user input.

**Sharing and field-level security**
- The class is declared `with sharing`.
- The query runs with `AccessLevel.USER_MODE`, so the platform applies the running user's sharing and field-level security.
- The class also checks object and field access up front. A denied object or field produces a clear `SearchException` instead of a platform exception.

**Validation**
- `maxRows` must be between 1 and 200.
- The object must exist and be readable and queryable.
- `fields` must not be null or empty.
- Every name in `fields`, the filter keys and `orderByField` must be a real field the user can read. Filter fields must be filterable, and the order-by field must be sortable.
- Duplicate field names, including an explicit `Id`, are removed so the query stays valid.

**Filter values**
- A null value is bound as is, so the condition matches records where that field is empty.
- When the UI sends a String for a Boolean, date, datetime or number field, it is converted to that field's type. A value that can't be converted throws `SearchException`.
- Collections and other unsupported value types are rejected.

**Single exception type**
- The public method catches any other exception and rethrows it as `SearchException`.
- The one exception it cannot convert is a governor limit error, because Apex cannot catch those.

