/**
 * Parses order payloads posted by the e-commerce platform and builds acknowledgements.
 *
 * Parsing uses JSON.deserializeUntyped because the payload's keys ("number", "date",
 * "currency") are Apex reserved words and cannot be mapped onto typed fields. It also lets
 * us validate every value explicitly. Any failure during parsing is reported as a
 * PayloadException, and no other exception type escapes.
 */
public with sharing class OrderPayloadParser {

    private static final Decimal MAX_INTEGER = Decimal.valueOf(2147483647);
    private static final Pattern ISO_DATE = Pattern.compile('^(\\d{4})-(\\d{2})-(\\d{2})$');

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = 0;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty.');
        }
        try {
            return parseInternal(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required to build an acknowledgement.');
        }
        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total;
        if (total == null) {
            total = 0;
            if (order.lines != null) {
                for (Line l : order.lines) {
                    if (l != null && l.lineTotal != null) {
                        total += l.lineTotal;
                    }
                }
            }
        }

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        if (order.orderNumber == null) {
            gen.writeNullField('number');
        } else {
            gen.writeStringField('number', order.orderNumber);
        }
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    // ---------------------------------------------------------------------------------
    // Internal helpers
    // ---------------------------------------------------------------------------------

    private static Order parseInternal(String body) {
        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }
        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object.');
        }
        Map<String, Object> data = (Map<String, Object>) root;

        Order order = new Order();

        // number (required, non-blank)
        String orderNumber = asString(data.get('number'), 'number');
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Order "number" is required.');
        }
        order.orderNumber = orderNumber;

        // date (optional, ISO yyyy-MM-dd)
        Object rawDate = data.get('date');
        if (rawDate != null) {
            order.orderDate = parseIsoDate(asString(rawDate, 'date'));
        }

        // currency (optional)
        order.currencyCode = asString(data.get('currency'), 'currency');

        // customer (optional)
        Object rawCustomer = data.get('customer');
        if (rawCustomer instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) rawCustomer;
            order.customerEmail = asString(customer.get('email'), 'customer.email');
        } else if (rawCustomer != null) {
            throw new PayloadException('"customer" must be a JSON object.');
        }

        // lines (optional, defaults to empty)
        Object rawLines = data.get('lines');
        order.lines = new List<Line>();
        Decimal total = 0;
        if (rawLines != null) {
            if (!(rawLines instanceof List<Object>)) {
                throw new PayloadException('"lines" must be a JSON array.');
            }
            Integer index = 0;
            for (Object rawLine : (List<Object>) rawLines) {
                Line l = parseLine(rawLine, index);
                order.lines.add(l);
                total += l.lineTotal;
                index++;
            }
        }
        order.total = total.setScale(2, RoundingMode.HALF_UP);
        return order;
    }

    private static Line parseLine(Object rawLine, Integer index) {
        String ctx = 'lines[' + index + ']';
        if (!(rawLine instanceof Map<String, Object>)) {
            throw new PayloadException(ctx + ' must be a JSON object.');
        }
        Map<String, Object> m = (Map<String, Object>) rawLine;
        Line l = new Line();

        // sku (required)
        Object rawSku = m.get('sku');
        if (rawSku == null) {
            throw new PayloadException(ctx + '.sku is required.');
        }
        l.sku = asString(rawSku, ctx + '.sku');

        // quantity (required, positive integer)
        Object rawQty = m.get('quantity');
        if (rawQty == null) {
            throw new PayloadException(ctx + '.quantity is required.');
        }
        Decimal qty = asDecimal(rawQty, ctx + '.quantity');
        if (qty <= 0) {
            throw new PayloadException(ctx + '.quantity must be positive.');
        }
        if (qty.round(System.RoundingMode.DOWN) != qty) {
            throw new PayloadException(ctx + '.quantity must be a whole number.');
        }
        if (qty > MAX_INTEGER) {
            throw new PayloadException(ctx + '.quantity is too large.');
        }
        l.quantity = qty.intValue();

        // unitPrice (required, non-negative)
        Object rawPrice = m.get('unitPrice');
        if (rawPrice == null) {
            throw new PayloadException(ctx + '.unitPrice is required.');
        }
        Decimal price = asDecimal(rawPrice, ctx + '.unitPrice');
        if (price < 0) {
            throw new PayloadException(ctx + '.unitPrice must not be negative.');
        }
        l.unitPrice = price;

        // discount (optional fraction 0..1, defaults to 0)
        Object rawDiscount = m.get('discount');
        Decimal discount = rawDiscount == null ? 0 : asDecimal(rawDiscount, ctx + '.discount');
        if (discount < 0 || discount > 1) {
            throw new PayloadException(ctx + '.discount must be between 0 and 1.');
        }
        l.discount = discount;

        l.lineTotal = (Decimal.valueOf(l.quantity) * price * (1 - discount))
            .setScale(2, RoundingMode.HALF_UP);
        return l;
    }

    private static String asString(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        if (value instanceof Map<String, Object> || value instanceof List<Object>) {
            throw new PayloadException('"' + field + '" must be a scalar value.');
        }
        return String.valueOf(value);
    }

    private static Decimal asDecimal(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof String || value instanceof Boolean
                || value instanceof Map<String, Object> || value instanceof List<Object>) {
            throw new PayloadException('"' + field + '" must be a number.');
        }
        try {
            if (value instanceof Decimal) {
                return (Decimal) value;
            }
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception e) {
            throw new PayloadException('"' + field + '" must be a number.');
        }
    }

    private static Date parseIsoDate(String value) {
        if (value == null) {
            return null;
        }
        Matcher mt = ISO_DATE.matcher(value.trim());
        if (!mt.matches()) {
            throw new PayloadException('"date" must use the format yyyy-MM-dd.');
        }
        Integer y = Integer.valueOf(mt.group(1));
        Integer mo = Integer.valueOf(mt.group(2));
        Integer d = Integer.valueOf(mt.group(3));
        if (mo < 1 || mo > 12 || d < 1 || d > Date.daysInMonth(y, mo)) {
            throw new PayloadException('"date" is not a valid calendar date.');
        }
        return Date.newInstance(y, mo, d);
    }
}
```

**Assumptions** (where the spec left room for interpretation):

- **Parsing approach:** The payload's keys `number`, `date` and `currency` are Apex reserved words. So the parser reads the JSON as an untyped map rather than mapping it onto typed fields. Unknown keys are ignored.
- **Single exception type:** Every failure during parsing is caught and rethrown as `PayloadException`, so no other exception type can escape.
- **`discount`:** A value outside 0 to 1 is rejected with `PayloadException`. The task describes it as a fraction between 0 and 1, but didn't list this as an error case.
- **`quantity`:** It must be a whole positive number. Values like `1.5` and quoted strings like `"2"` are rejected.
- **`date`:** It must be a real calendar date in exactly `yyyy-MM-dd` form, so `2026-02-30` is rejected. A missing or null date gives a null `orderDate`.
- **Wrong structure:** `customer` that isn't an object, `lines` that isn't an array, or a line that isn't an object all throw `PayloadException`.
- **`sku`:** Only a missing or null `sku` is rejected; a blank string is allowed. The spec says "missing or blank" for `number` but only "missing" for `sku`.
- **Rounding:** Each `lineTotal` is rounded half-up to 2 decimals using exact decimal arithmetic. `total` is the sum of the rounded line totals.
- **`toAcknowledgement`:** It writes the four keys in a fixed order with `lineCount` and `total` as JSON numbers. If `total` is null, it falls back to summing the line totals.

The test class has one configurable `HttpCalloutMock`. The mock records every request it receives and how many callouts were made. Each test then checks one part of the documented behaviour against the class:

- **Request contract:** the method, the endpoint, the `Content-Type` header, the JSON key names, the four values (none swapped) and no extra keys. One test also checks that billing fields with no value still go out as JSON `null`.
- **Skip rule:** a null, empty or whitespace-only street returns `SKIPPED` and makes no callout.
- **Error handling:** responses 201, 204, 302, 400, 404, 500 and 503 must each throw `AddressVerificationException`, and the message must contain the status code. The account must also stay unchanged.
- **CORRECTED:** all four billing fields are overwritten and `changed` is true.
- **VERIFIED and INVALID:** these responses carry a different address, so the test proves the account is left unchanged and `changed` is false.

