@IsTest
private class OpportunityWonHandlerTest {
    private static final String WON = 'Closed Won';
    private static final String OPEN = 'Prospecting';
    private static final String LOST = 'Closed Lost';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final String SUBJECT = 'Customer kick-off';
    private static final Date CLOSE = Date.newInstance(2030, 1, 15);
    private static final Date EXPECTED_ACTIVITY = Date.newInstance(2030, 1, 22);

    // ---------------------------------------------------------------- helpers

    private static User otherUser() {
        User u;
        System.runAs(new User(Id = UserInfo.getUserId())) {
            String uniq = String.valueOf(Math.abs(Crypto.getRandomInteger()))
                + String.valueOf(Datetime.now().getTime());
            User candidate = new User(
                ProfileId = UserInfo.getProfileId(),
                Username = 'owht' + uniq + '@example.com.test',
                Email = 'owht' + uniq + '@example.com.test',
                LastName = 'HandoverOwner',
                Alias = 'owht',
                EmailEncodingKey = 'UTF-8',
                LanguageLocaleKey = 'en_US',
                LocaleSidKey = 'en_US',
                TimeZoneSidKey = 'America/Los_Angeles'
            );
            try {
                insert candidate;
                u = candidate;
            } catch (DmlException e) {
                u = null;
            }
        }
        if (u == null) {
            List<User> existing = [
                SELECT Id FROM User
                WHERE IsActive = true
                AND UserType = 'Standard'
                AND ProfileId = :UserInfo.getProfileId()
                AND Id != :UserInfo.getUserId()
                LIMIT 1
            ];
            if (!existing.isEmpty()) {
                u = existing[0];
            } else {
                u = new User(Id = UserInfo.getUserId());
            }
        }
        return u;
    }

    private static Account newAccount(String name, String rating) {
        return new Account(Name = name, Rating = rating);
    }

    private static Opportunity newOpp(String name, String stage, Id accountId) {
        return new Opportunity(
            Name = name,
            StageName = stage,
            CloseDate = CLOSE,
            AccountId = accountId
        );
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
        ];
    }

    private static List<Task> tasksFor(Id oppId) {
        return tasksFor(new Set<Id>{ oppId });
    }

    private static Opportunity reload(Id oppId) {
        return [SELECT Id, NextStep, StageName, OwnerId FROM Opportunity WHERE Id = :oppId];
    }

    private static String ratingOf(Id accountId) {
        return [SELECT Rating FROM Account WHERE Id = :accountId].Rating;
    }

    private static void assertKickoffTask(Task t, Id oppId, Id ownerId) {
        Assert.areEqual(SUBJECT, t.Subject, 'Task subject');
        Assert.areEqual(oppId, t.WhatId, 'Task WhatId must be the opportunity');
        Assert.areEqual(ownerId, t.OwnerId, 'Task owner must be the opportunity owner');
        Assert.areEqual(EXPECTED_ACTIVITY, t.ActivityDate, 'ActivityDate must be CloseDate + 7 days');
        Assert.areEqual('High', t.Priority, 'Task priority');
    }

    // ---------------------------------------------------------------- insert

    @IsTest
    static void insertWonSetsNextStepCreatesTaskAndRatesAccountHot() {
        User owner = otherUser();
        Account acc = newAccount('Won Insert Account', 'Cold');
        insert acc;

        Opportunity opp = newOpp('Won Insert', WON, acc.Id);
        opp.OwnerId = owner.Id;
        opp.NextStep = 'Something else';

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity saved = reload(opp.Id);
        Assert.areEqual(HANDOVER, saved.NextStep, 'NextStep must be set on newly won insert');
        Assert.areEqual(owner.Id, saved.OwnerId, 'Owner should be as inserted');

        List<Task> tasks = tasksFor(opp.Id);
        Assert.areEqual(1, tasks.size(), 'Exactly one kick-off task expected');
        assertKickoffTask(tasks[0], opp.Id, owner.Id);

        Assert.areEqual('Hot', ratingOf(acc.Id), 'Account must be rated Hot');
    }

    @IsTest
    static void insertWonWithBlankRatingAccountRatesHot() {
        Account acc = newAccount('Blank Rating Account', null);
        insert acc;

        Test.startTest();
        insert newOpp('Won Blank Rating', WON, acc.Id);
        Test.stopTest();

        Assert.areEqual('Hot', ratingOf(acc.Id), 'Account without rating must become Hot');
    }

    @IsTest
    static void insertNonWonChangesNothing() {
        Account acc = newAccount('Open Account', 'Cold');
        insert acc;

        Opportunity openOpp = newOpp('Open Insert', OPEN, acc.Id);
        openOpp.NextStep = 'Keep me';
        Opportunity lostOpp = newOpp('Lost Insert', LOST, acc.Id);
        lostOpp.NextStep = 'Keep me too';

        Test.startTest();
        insert new List<Opportunity>{ openOpp, lostOpp };
        Test.stopTest();

        Assert.areEqual('Keep me', reload(openOpp.Id).NextStep, 'NextStep must not change for non-won insert');
        Assert.areEqual('Keep me too', reload(lostOpp.Id).NextStep, 'NextStep must not change for lost insert');
        Assert.areEqual(0, tasksFor(new Set<Id>{ openOpp.Id, lostOpp.Id }).size(), 'No tasks for non-won inserts');
        Assert.areEqual('Cold', ratingOf(acc.Id), 'Account rating must not change');
