/**
 * Returns the active values of any picklist or multi-select picklist field,
 * with the object and field chosen at runtime.
 *
 * Object and field API names are case-insensitive. They may be standard or custom,
 * and may include a namespace prefix.
 */
public with sharing class PicklistService {

    /**
     * One active picklist value.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault == true;
        }
    }

    /**
     * Thrown for any invalid input: blank names, an unknown object or field,
     * or a field that is not a picklist or multi-select picklist.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist or multi-select picklist field,
     * in the order they are defined on the field.
     *
     * @param objectApiName  API name of the SObject (case-insensitive)
     * @param fieldApiName   API name of the field (case-insensitive)
     * @return list of active options in definition order
     * @throws PicklistServiceException when the input is invalid
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be blank.');
        }

        String objectName = objectApiName.trim();
        String fieldName = fieldApiName.trim();

        Schema.DescribeSObjectResult objectDescribe = describeObject(objectName);

        // The field map is case-insensitive.
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldName);
        if (field == null) {
            throw new PicklistServiceException(
                'Field "' + fieldName + '" does not exist on object "' + objectDescribe.getName() + '".'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field "' + fieldDescribe.getName() + '" on object "' + objectDescribe.getName()
                + '" is not a picklist or multi-select picklist.'
            );
        }

        List<Option> options = new List<Option>();
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        if (entries == null) {
            return options;
        }
        // getPicklistValues() returns entries in the order they are defined on the field.
        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }
        return options;
    }

    /**
     * Describes a single SObject by name. This avoids the cost of a full global describe.
     * Any failure is turned into a PicklistServiceException.
     */
    private static Schema.DescribeSObjectResult describeObject(String objectName) {
        // A comma would make describeSObjects treat the input as several object names.
        if (objectName.contains(',')) {
            throw new PicklistServiceException('Object "' + objectName + '" does not exist.');
        }
        List<Schema.DescribeSObjectResult> results;
        try {
            results = Schema.describeSObjects(new List<String>{ objectName });
        } catch (Exception e) {
            // Unknown object names throw System.InvalidParameterValueException.
            throw new PicklistServiceException('Object "' + objectName + '" does not exist.');
        }
        if (results == null || results.size() != 1 || results[0] == null) {
            throw new PicklistServiceException('Object "' + objectName + '" does not exist.');
        }
        return results[0];
    }
}
```

**Notes:**
- **Object lookup:** It uses `Schema.describeSObjects` for just the requested object instead of `Schema.getGlobalDescribe()`. This is cheaper, and the lookup is case-insensitive. An unknown name throws `InvalidParameterValueException`, which the class catches and rethrows as `PicklistServiceException`.
- **Field lookup:** The field map from `fields.getMap()` is case-insensitive, so `account` / `INDUSTRY` resolve correctly.
- **Value order:** `getPicklistValues()` keeps the order defined on the field. Inactive values are filtered out with `isActive()`, and `isDefault` comes from `isDefaultValue()`.
- **Error handling:** Every invalid-input path (blank names, unknown object or field, wrong field type) throws `PicklistServiceException`. No raw NullPointerException or describe exception reaches the caller.

