/**
 * Re-rates Accounts from AnnualRevenue in chained Queueable executions.
 * Each execution handles at most BATCH_SIZE accounts (1 SOQL, 1 DML) and
 * enqueues a new AccountScoringJob with the remaining Ids.
 */
public with sharing class AccountScoringJob implements Queueable {

    @TestVisible
    private static final Integer BATCH_SIZE = 200;

    private static final Decimal HOT_THRESHOLD  = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * Enqueues the first job of the chain and returns its job Id.
     * Returns null (and enqueues nothing) for a null or empty list.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return enqueueNewChain(new AccountScoringJob(accountIds), accountIds.size());
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer total = accountIds.size();
        Integer currentCount = Math.min(BATCH_SIZE, total);

        Set<Id> currentIds = new Set<Id>();
        for (Integer i = 0; i < currentCount; i++) {
            if (accountIds[i] != null) {
                currentIds.add(accountIds[i]);
            }
        }

        if (!currentIds.isEmpty()) {
            // One SOQL query
            List<Account> accounts = [
                SELECT Id, AnnualRevenue, Rating
                FROM Account
                WHERE Id IN :currentIds
                WITH USER_MODE
            ];
            for (Account acc : accounts) {
                acc.Rating = ratingFor(acc.AnnualRevenue);
            }
            // One DML statement
            if (!accounts.isEmpty()) {
                update as user accounts;
            }
        }

        // Chain the remainder
        if (total > currentCount) {
            List<Id> remaining = new List<Id>();
            for (Integer i = currentCount; i < total; i++) {
                remaining.add(accountIds[i]);
            }
            enqueueNext(new AccountScoringJob(remaining), remaining.size());
        }
    }

    @TestVisible
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return 'Hot';
        }
        if (annualRevenue >= WARM_THRESHOLD) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * Enqueues the next job. Inside an existing chain the child inherits the
     * chain's configured maximum stack depth. Outside a queueable chain
     * (e.g. execute(null) called directly) a new chain is started with
     * an explicit stack depth sized for the remaining work.
     */
    private static Id enqueueNext(AccountScoringJob job, Integer remainingCount) {
        if (Limits.getQueueableJobs() >= Limits.getLimitQueueableJobs()) {
            return null;
        }
        Boolean inChain = (System.isQueueable() && AsyncInfo.getCurrentQueueableStackDepth() > 0);
        if (inChain) {
            return System.enqueueJob(job);
        }
        return enqueueNewChain(job, remainingCount);
    }

    /**
     * Starts a new chain with an explicit maximum stack depth large enough
     * for every job needed. This overrides the low default depth of
     * Developer Edition/trial orgs and lets the whole chain run within
     * Test.startTest()/Test.stopTest().
     */
    private static Id enqueueNewChain(AccountScoringJob job, Integer idCount) {
        Integer jobsNeeded = (Integer) Math.ceil(Decimal.valueOf(idCount) / BATCH_SIZE);
        AsyncOptions options = new AsyncOptions();
        // +1 as a small safety margin; the initial job counts as depth 1.
        options.MaximumQueueableStackDepth = Math.max(2, jobsNeeded + 1);
        return System.enqueueJob(job, options);
    }
}
```

- **One query, one DML:** each execution takes the first 200 Ids, makes one query, and does one update. If none of those Ids match an account, it skips the update. It ignores null Ids in the list.
- **Chaining:** `start` begins the chain and sizes its depth to the number of jobs needed, plus a small margin. Jobs further down the chain enqueue the next job plainly and inherit that depth. Chaining stays on during tests.
- **`execute(null)` called directly:** this works. The context isn't used. If called outside a chain with more than 200 Ids, the job starts a new chain for the rest, again with a sized depth.
- **Permissions:** the class uses `with sharing`, a query `WITH USER_MODE`, and `update as user`. The job runs as the user who clicked the button, so their sharing and field-level security apply. That user needs edit access to `Rating`, or the update fails.

