/**
 * Marks accounts as synced to the ERP.
 *
 * Every run attaches an ErpSyncFinalizer before doing any work. The finalizer
 * logs the outcome and retries failed runs, up to 3 attempts in total.
 *
 * The update is all-or-nothing and is deliberately NOT wrapped in a try/catch.
 * If any account fails to save, the job fails, its DML is rolled back, and the
 * finalizer sees the failure.
 *
 * The class is "with sharing": a Queueable runs as the user who enqueued it,
 * so that user's record access is enforced.
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    @TestVisible
    private static final String SYNCED_DESCRIPTION = 'Synced to ERP';

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        // Defensive copy so later changes by the caller cannot affect this job.
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = (attempt == null || attempt < 1) ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer first, so even an early failure is logged and retried.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, Description = SYNCED_DESCRIPTION));
        }

        // All-or-nothing. Any failure throws a DmlException, the job fails and nothing is kept.
        update accountsToUpdate;
    }
}
