/**
 * Maintains Account.FB_Open_Pipeline__c (sum of Amount of open opportunities, blank = 0)
 * and Account.FB_Open_Opportunities__c (number of open opportunities).
 *
 * Totals are always recomputed from the database (never incremented), so they are correct
 * after every DML statement, including repeated DML on the same records in one transaction.
 *
 * Runs without sharing on purpose: the totals are a system-maintained summary that must include
 * every opportunity of the account, including those the running user cannot see, and must be
 * written even if the user cannot edit the Account.
 */
public without sharing class OpportunityPipelineHandler {

    private static final Integer MAX_PASSES = 10;

    // Re-entrancy guard (NOT a "run once" flag): it is only true while this class is itself
    // updating Accounts, and is always reset in a finally block.
    private static Boolean isRecalculating = false;
    private static Set<Id> pendingAccountIds = new Set<Id>();

    public class PipelineException extends Exception {}

    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();
        List<Opportunity> contextRecords;

        switch on operation {
            when AFTER_INSERT, AFTER_UNDELETE {
                contextRecords = newList;
                for (Opportunity opp : newList) {
                    accountIds.add(opp.AccountId);
                }
            }
            when AFTER_UPDATE {
                contextRecords = newList;
                for (Opportunity opp : newList) {
                    Opportunity oldOpp = oldMap.get(opp.Id);
                    // Only changes that can affect the totals. This also stops the recursion
                    // through AccountTrigger, which only changes FB_Account_Rating__c.
                    if (opp.AccountId != oldOpp.AccountId
                        || opp.IsClosed != oldOpp.IsClosed
                        || opp.Amount != oldOpp.Amount) {
                        accountIds.add(opp.AccountId);
                        accountIds.add(oldOpp.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                contextRecords = oldMap.values();
                for (Opportunity opp : oldMap.values()) {
                    accountIds.add(opp.AccountId);
                }
            }
            when else {
                return;
            }
        }

        recalculate(accountIds, contextRecords);
    }

    private static void recalculate(Set<Id> accountIds, List<Opportunity> contextRecords) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        pendingAccountIds.addAll(accountIds);
        if (isRecalculating) {
            // We are inside our own Account update (e.g. AccountTrigger -> Opportunity update ->
            // some automation changed amounts). The outer invocation processes the queue.
            return;
        }

        isRecalculating = true;
        Map<Id, String> failures = new Map<Id, String>();
        try {
            Integer passes = 0;
            while (!pendingAccountIds.isEmpty()) {
                passes++;
                if (passes > MAX_PASSES) {
                    throw new PipelineException(
                        'Open pipeline totals did not stabilise after ' + MAX_PASSES
                        + ' recalculation passes; check automation that changes opportunities '
                        + 'when accounts are updated.'
                    );
                }
                Set<Id> batch = new Set<Id>(pendingAccountIds);
                pendingAccountIds.clear();

                Map<Id, String> passFailures = recalculateNow(batch);
                // A later successful pass for the same account supersedes an earlier failure.
                for (Id accId : batch) {
                    if (!passFailures.containsKey(accId)) {
                        failures.remove(accId);
                    }
                }
                failures.putAll(passFailures);
            }
        } finally {
            isRecalculating = false;
            pendingAccountIds.clear();
        }

        reportFailures(failures, contextRecords);
    }

    /**
     * Recomputes and stores the totals for the given accounts.
     * Returns a map of AccountId -> error message for accounts that could not be saved.
     */
    private static Map<Id, String> recalculateNow(Set<Id> accountIds) {
        Map<Id, String> failures = new Map<Id, String>();

        // Lock the accounts first so concurrent loads cannot interleave recalculations.
        // Accounts that no longer exist are simply not returned.
        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ]);
        if (accounts.isEmpty()) {
            return failures;
        }

        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accounts.keySet() AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total'); // SUM ignores blank amounts; null if all blank
            pipelineByAccount.put(accId, total == null ? 0 : total);
            countByAccount.put(accId, (Integer) ar.get('cnt'));
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts.values()) {
            Decimal newPipeline = pipelineByAccount.containsKey(acc.Id) ? pipelineByAccount.get(acc.Id) : 0;
            Decimal newCount = countByAccount.containsKey(acc.Id) ? countByAccount.get(acc.Id) : 0;

            // Only write when something changed (null != 0, so blanks are normalised to 0).
            if (acc.FB_Open_Pipeline__c != newPipeline || acc.FB_Open_Opportunities__c != newCount) {
                toUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (toUpdate.isEmpty()) {
            return failures;
        }

        List<Database.SaveResult> results = Database.update(toUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                failures.put(toUpdate[i].Id, String.join(messages, '; '));
            }
        }
        return failures;
    }

    /**
     * Surfaces account save failures on the opportunities that caused them, so the
     * opportunity DML fails (allOrNone) or only the affected rows fail (partial success / data loads).
     */
    private static void reportFailures(Map<Id, String> failures, List<Opportunity> contextRecords) {
        if (failures.isEmpty()) {
            return;
        }

        Set<Id> attributed = new Set<Id>();
        Map<Id, Opportunity> oldMap = Trigger.isExecuting && Trigger.isUpdate
            ? (Map<Id, Opportunity>) Trigger.oldMap
            : null;

        if (contextRecords != null) {
            for (Opportunity opp : contextRecords) {
                Id failedAccountId = null;
                if (opp.AccountId != null && failures.containsKey(opp.AccountId)) {
                    failedAccountId = opp.AccountId;
                } else if (oldMap != null && oldMap.containsKey(opp.Id)) {
                    Id oldAccountId = oldMap.get(opp.Id).AccountId;
                    if (oldAccountId != null && failures.containsKey(oldAccountId)) {
                        failedAccountId = oldAccountId;
                    }
                }
                if (failedAccountId != null) {
                    opp.addError('Could not update open pipeline totals on account '
                        + failedAccountId + ': ' + failures.get(failedAccountId));
                    attributed.add(failedAccountId);
                }
            }
        }

        // Failures that cannot be tied to a record in this trigger context must still fail the transaction.
        for (Id accId : failures.keySet()) {
            if (!attributed.contains(accId)) {
                throw new PipelineException('Could not update open pipeline totals on account '
                    + accId + ': ' + failures.get(accId));
            }
        }
    }
}
```

The class implements both `Schedulable` and `Database.Batchable`, so the answer stays in one file and still scales:

- **Small backlogs** (up to 9,000 records) are deleted directly in the scheduled run. This stays under the 10,000 DML-row limit.
- **Larger backlogs** are handed to a batch run of the same class, 2,000 records per chunk. Storage is "filling up", so one run may need to remove far more than one transaction allows.

