/**
 * Purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Logs whose Level__c is ERROR are kept until they were created more than 180 days ago.
 *  - All other logs, including logs with a blank Level__c, are deleted once they were
 *    created more than 30 days ago.
 *
 * Small backlogs are purged directly in the scheduled transaction. Large backlogs are handed
 * off to a batch run of this same class so the job never hits DML or row limits.
 *
 * Runs "without sharing" on purpose: this is a system maintenance job that must purge every
 * qualifying log, whatever the sharing access of the user who scheduled it.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String NIGHTLY_CRON = '0 0 2 * * ?'; // every day at 02:00

    @TestVisible
    private static final Integer DEFAULT_RETENTION_DAYS = 30;
    @TestVisible
    private static final Integer ERROR_RETENTION_DAYS = 180;
    @TestVisible
    private static final String ERROR_LEVEL = 'ERROR';

    // Max records deleted directly in the scheduled transaction (below the 10,000 DML row limit).
    @TestVisible
    private static final Integer SYNC_DELETE_LIMIT = 9000;
    @TestVisible
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    /**
     * Schedules the purge to run every day at 02:00.
     * @return the CronTrigger Id returned by System.schedule
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    // ---------------------------------------------------------------------------------------
    // Schedulable
    // ---------------------------------------------------------------------------------------

    public void execute(SchedulableContext context) {
        Datetime defaultCutoff = System.now().addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = System.now().addDays(-ERROR_RETENTION_DAYS);
        Integer probeLimit = SYNC_DELETE_LIMIT + 1;

        List<FB_Integration_Log__c> candidates = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :defaultCutoff
                    AND (Level__c = null OR Level__c != :ERROR_LEVEL))
               OR CreatedDate < :errorCutoff
            LIMIT :probeLimit
        ];

        if (candidates.isEmpty()) {
            return;
        }

        if (candidates.size() <= SYNC_DELETE_LIMIT) {
            deleteRecords(candidates);
        } else {
            // Too many for one transaction: purge everything in chunks.
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // ---------------------------------------------------------------------------------------
    // Batchable (used for large backlogs)
    // ---------------------------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime defaultCutoff = System.now().addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = System.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :defaultCutoff
                    AND (Level__c = null OR Level__c != :ERROR_LEVEL))
               OR CreatedDate < :errorCutoff
        ]);
    }

    public void execute(Database.BatchableContext context, List<SObject> scope) {
        deleteRecords(scope);
    }

    public void finish(Database.BatchableContext context) {
        // Nothing further required.
    }

    // ---------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------

    private static void deleteRecords(List<SObject> records) {
        if (records == null || records.isEmpty()) {
            return;
        }
        // Partial success: one locked or failing record must not block the rest of the purge.
        // Records that fail are retried on the next nightly run.
        List<Database.DeleteResult> results = Database.delete(records, false, AccessLevel.SYSTEM_MODE);
        for (Database.DeleteResult result : results) {
            if (!result.isSuccess()) {
                for (Database.Error err : result.getErrors()) {
                    System.debug(LoggingLevel.WARN,
                        'LogPurgeJob could not delete ' + result.getId() + ': ' + err.getMessage());
                }
            }
        }
    }
}
```

**Design notes**
- **Delete filter:** a log is deleted when it was created more than 30 days ago and its level is not `ERROR`, or when it was created more than 180 days ago.
- **Cutoff time:** "more than N days ago" is measured with `CreatedDate < now - N days`.
- **Case:** SOQL string comparison is case-insensitive, so `error` and `Error` are kept as errors too.
- **Blank levels:** the explicit `Level__c = null` check makes sure logs with no level are always purged after 30 days.
- **Testing:** if a test schedules the job with a large backlog, the batch it starts will not run in the test context. Test data normally stays below 9,000 records, so the direct delete path covers it.
- **Sharing and access:** the job runs `without sharing` and uses system-mode DML. This is deliberate, because a maintenance purge must work whatever the access of the user who scheduled it.
- **Failures:** deletes allow partial success, so one locked record does not stop the rest. Failed records are logged and picked up again on the next nightly run.

