/**
 * Rolls up closed-won opportunity revenue per account for the current calendar year.
 * Runs with sharing so only opportunities visible to the running user are included.
 */
public with sharing class OpportunityRollupService {

    /**
     * Returns, for each requested account Id, the sum of Amount over its won opportunities
     * whose CloseDate falls in the current calendar year. Accounts with no qualifying
     * opportunities (or only blank amounts) map to 0. A null or empty input returns an empty map.
     *
     * @param accountIds the account Ids to roll up
     * @return map of account Id to won amount for this calendar year (never null values)
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Defensive copy without nulls: we must not change the caller's set,
        // and a null in an IN bind would match opportunities with no account.
        Set<Id> ids = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                ids.add(accountId);
                result.put(accountId, 0);
            }
        }
        if (ids.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :ids
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total');
            // Only requested Ids are ever keys; SUM over only-null amounts yields null -> 0.
            if (result.containsKey(accId)) {
                result.put(accId, total == null ? 0 : total);
            }
        }

        return result;
    }
}
