/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage.
 * No DML and no SOQL: the selector is replaced with an ApexMocks mock registered
 * through Application.Selector.setMock and all records are built in memory with
 * fake ids from fflib_IDGenerator.
 */
@IsTest
private class OpportunityForecastServiceTest {

    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_NEGOTIATION = 'Negotiation/Review';
    private static final String STAGE_QUALIFICATION = 'Qualification';

    @IsTest
    static void sumsWeightedAmountPerStageRoundingEachOpportunity() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        Id accountId1 = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> opportunities = new List<Opportunity>{
            // 333.34 * 10 / 100 = 33.334 -> 33.33 each; per-opportunity rounding gives 66.66
            // (rounding only the total would give 66.67)
            buildOpportunity(accountId1, STAGE_PROSPECTING, 333.34, 10),
            buildOpportunity(accountId2, STAGE_PROSPECTING, 333.34, 10),
            // 1000 * 75 / 100 = 750.00
            buildOpportunity(accountId1, STAGE_NEGOTIATION, 1000.00, 75),
            // 250.50 * 20 / 100 = 50.10 -> negotiation total 800.10
            buildOpportunity(accountId2, STAGE_NEGOTIATION, 250.50, 20)
        };

        mocks.startStubbing();
        mocks.when(mockSelector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();
        Application.Selector.setMock(mockSelector);

        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        Assert.isNotNull(result, 'The service must never return null');
        Assert.areEqual(
            new Set<String>{ STAGE_PROSPECTING, STAGE_NEGOTIATION },
            result.keySet(),
            'There must be exactly one entry per stage of the returned opportunities'
        );
        Assert.areEqual(66.66, result.get(STAGE_PROSPECTING),
            'Prospecting must be the sum of each opportunity weighted amount rounded to 2 decimals');
        Assert.areEqual(800.10, result.get(STAGE_NEGOTIATION),
            'Negotiation/Review must be the sum of Amount * Probability / 100 of its opportunities');

        ((IOpportunitiesSelector) mocks.verify(mockSelector, 1)).selectOpenByAccountIds(accountIds);
    }

