/**
 * Central application factory configuration (fflib Apex Enterprise Patterns).
 *
 * NOTE: Field declaration order matters. Static initialisers run top to bottom,
 * and the Domain factory needs the already-initialised Selector factory instance.
 */
public inherited sharing class Application {

    /**
     * Unit of Work factory.
     * SObjectTypes are listed in dependency order (parents before children) so that
     * a single commitWork() can insert Accounts, then Contacts and Opportunities
     * related to those Accounts, then OpportunityContactRoles linking the new
     * Opportunities and Contacts. Relationships are resolved by the unit of work.
     */
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    /**
     * Service factory: maps service interfaces to their implementations.
     */
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type>{
                IAccountsService.class => AccountsServiceImpl.class
            }
        );

    /**
     * Selector factory: maps SObjectTypes to their selector implementations.
     */
    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => AccountsSelector.class,
                Contact.SObjectType => ContactsSelector.class
            }
        );

    /**
     * Domain factory: maps SObjectTypes to their domain constructor classes.
     * Uses the Selector factory above so that newInstance(Set<Id>) queries records
     * through the configured (and mockable) selectors.
     */
    public static final fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(
            Application.Selector,
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => Accounts.Constructor.class
            }
        );
}
