/**
 * Domain class for Opportunity.
 *
 * Starts fulfilment for opportunities that become Closed Won:
 *  - inserted with StageName = 'Closed Won', or
 *  - updated so that StageName changes to 'Closed Won' from any other stage.
 *
 * Per trigger invocation the fulfilment service is called at most once, with the
 * ids of all qualifying opportunities, and not at all if none qualify.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    @TestVisible
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (isClosedWon(opp.StageName)) {
                qualifyingIds.add(opp.Id);
            }
        }
        startFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            Boolean wasClosedWon = oldOpp != null && isClosedWon(oldOpp.StageName);
            if (isClosedWon(opp.StageName) && !wasClosedWon) {
                qualifyingIds.add(opp.Id);
            }
        }
        startFulfilment(qualifyingIds);
    }

    private static Boolean isClosedWon(String stageName) {
        return stageName != null && stageName == STAGE_CLOSED_WON;
    }

    private static void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
