/**
 * Domain class for Opportunity.
 *
 * Validation rules:
 *  1. Insert and update: Amount must not be negative.
 *  2. Update: if the stage was already 'Closed Won' before the update, Amount cannot change.
 *     Closing as won and changing the amount in the same update is allowed.
 *
 * Validation runs in the fflib after-trigger hooks:
 *  - onValidate() runs after insert.
 *  - onValidate(Map<Id, SObject>) runs after update.
 *
 * Each error is attached to the Amount field of the offending record only, so partial-success
 * DML still saves the other records. Messages are passed through error(message, record, field)
 * so that fflib_SObjectDomain.Errors records them for unit tests.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    @TestVisible
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    @TestVisible
    private static final String ERROR_NEGATIVE_AMOUNT = 'Amount cannot be negative.';

    @TestVisible
    private static final String ERROR_WON_AMOUNT_CHANGED = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    /**
     * Validation on insert.
     */
    public override void onValidate()
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);
        }
    }

    /**
     * Validation on update.
     */
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);

            Opportunity oldOpp = (existingRecords == null)
                ? null
                : (Opportunity) existingRecords.get(opp.Id);

            if (oldOpp != null
                && oldOpp.StageName == STAGE_CLOSED_WON
                && opp.Amount != oldOpp.Amount)
            {
                opp.addError(
                    Opportunity.Amount,
                    error(ERROR_WON_AMOUNT_CHANGED, opp, Opportunity.Amount)
                );
            }
        }
    }

    private void validateAmountNotNegative(Opportunity opp)
    {
        if (opp.Amount != null && opp.Amount < 0)
        {
            opp.addError(
                Opportunity.Amount,
                error(ERROR_NEGATIVE_AMOUNT, opp, Opportunity.Amount)
            );
        }
    }

    /**
     * Standard fflib constructor used by fflib_SObjectDomain.triggerHandler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }
}
