/**
 * Selector for the Contact SObject (Apex Enterprise Patterns / fflib-apex-common).
 * All Contact queries should be routed through this class.
 */
public inherited sharing class ContactsSelector extends fflib_SObjectSelector {

    /**
     * The SObject type this selector queries.
     */
    public Schema.SObjectType getSObjectType() {
        return Contact.SObjectType;
    }

    /**
     * The default field list selected by every query issued through this selector.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Contact.Id,
            Contact.FirstName,
            Contact.LastName,
            Contact.Email,
            Contact.Title,
            Contact.AccountId
        };
    }

    /**
     * Returns the contacts with the given ids, with all fields of the selector's
     * field list populated, using a single SOQL query.
     * An empty (or null) set returns an empty list without issuing a query.
     *
     * @param contactIds ids of the contacts to retrieve
     * @return the matching contacts
     */
    public List<Contact> selectById(Set<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new List<Contact>();
        }
        return (List<Contact>) selectSObjectsById(contactIds);
    }
}
