/**
 * Service layer for escalating Cases.
 *
 * Reads go through the CasesSelector (resolved via Application.Selector) and writes go through
 * one unit of work (resolved via Application.UnitOfWork). Unit tests can therefore replace both
 * with ApexMocks using Application.Selector.setMock / Application.UnitOfWork.setMock.
 */
public with sharing class CaseEscalationService {

    @TestVisible
    private static final String STATUS_CLOSED = 'Closed';

    @TestVisible
    private static final String PRIORITY_HIGH = 'High';

    @TestVisible
    private static final String SUBJECT_PREFIX = 'Escalated: ';

    private static final Integer TASK_SUBJECT_MAX_LENGTH = 255;

    /**
     * Thrown when an escalation request is invalid.
     */
    public class EscalationException extends Exception {}

    /**
     * Escalates the given cases. Closed cases and cases that are already escalated are skipped.
     * Each escalated case gets IsEscalated = true and Priority = 'High', plus a follow-up Task.
     *
     * @param caseIds Ids of the cases to escalate. Null or empty means nothing to do.
     * @param reason  Escalation reason, used in the Task subject. Must not be blank.
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate before any read or write.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        List<Case> casesToEscalate = new List<Case>();
        for (Case c : cases) {
            if (c == null) {
                continue;
            }
            if (c.Status == STATUS_CLOSED) {
                continue;
            }
            if (c.IsEscalated == true) {
                continue;
            }
            casesToEscalate.add(c);
        }

        // Nothing to escalate: no unit of work and no commitWork() call.
        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        String taskSubject = (SUBJECT_PREFIX + reason).left(TASK_SUBJECT_MAX_LENGTH);
        Date dueDate = Date.today().addDays(1);

        for (Case c : casesToEscalate) {
            // Update only the fields that change, so other field values are not overwritten.
            Case updatedCase = new Case(
                Id = c.Id,
                IsEscalated = true,
                Priority = PRIORITY_HIGH
            );
            uow.registerDirty(updatedCase);

            Task followUp = new Task(
                Subject = taskSubject,
                WhatId = c.Id,
                OwnerId = resolveTaskOwner(c.OwnerId),
                ActivityDate = dueDate,
                Priority = PRIORITY_HIGH
            );
            uow.registerNew(followUp);
        }

        uow.commitWork();
    }

    /**
     * A Task can only be owned by a user. If the case is owned by a queue (or the owner is
     * unknown), assign the task to the running user so the commit does not fail.
     */
    private static Id resolveTaskOwner(Id caseOwnerId) {
        if (caseOwnerId != null && caseOwnerId.getSObjectType() == User.SObjectType) {
            return caseOwnerId;
        }
        return UserInfo.getUserId();
    }
}
