/**
 * Service for closing opportunities as won and notifying Fulfilment.
 *
 * Deal_Won__e is configured as "Publish Immediately", so publishing it before or
 * during the DML (via EventBus.publish, registerNew or registerPublishBeforeTransaction)
 * would leak events even if the save later fails and is rolled back.
 * The unit of work's "after success" event queue is published only after
 * all DML in commitWork() has completed successfully. If any DML fails, fflib
 * rolls back to its savepoint, publishes nothing from that queue and rethrows the exception.
 */
public with sharing class OpportunityWinService {

    @TestVisible
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> ids = new Set<Id>(opportunityIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(ids);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date today = Date.today();
        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            if (opp.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            // Only send the fields we change, to avoid overwriting concurrent edits to other fields.
            uow.registerDirty(new Opportunity(
                Id = opp.Id,
                StageName = STAGE_CLOSED_WON,
                CloseDate = today
            ));

            // Published by the unit of work only after the updates were committed successfully.
            uow.registerPublishAfterSuccessTransaction(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            ));

            closedCount++;
        }

        if (closedCount == 0) {
            return 0;
        }

        // Single commit; on failure fflib rolls back, publishes no Deal_Won__e and rethrows.
        uow.commitWork();

        return closedCount;
    }
}
