/**
 * Invocable action used by the Web_Signup_Match_Contact flow.
 * Matches each requested email to an existing Contact (case-insensitive,
 * ignoring leading/trailing whitespace). When several Contacts share an
 * email, the earliest created (then lowest Id) wins.
 * Uses at most one SOQL query per invocation regardless of request count.
 */
public with sharing class ContactEmailMatcher {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address to match against Contact.Email')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Matched Contact Id, or null when there is no match')
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email' description='Finds the earliest-created Contact whose Email matches each request (case-insensitive, trimmed).')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect normalized, non-blank emails
        Set<String> emailKeys = new Set<String>();
        for (Request req : requests) {
            String key = normalize(req == null ? null : req.email);
            if (key != null) {
                emailKeys.add(key);
            }
        }

        // Single query; SOQL string comparison is case-insensitive.
        // Ordered so the first Contact seen per email is the earliest created.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!emailKeys.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailKeys
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // Exactly one result per request, in the same order
        for (Request req : requests) {
            Result res = new Result();
            String key = normalize(req == null ? null : req.email);
            res.contactId = (key == null) ? null : contactIdByEmail.get(key);
            results.add(res);
        }
        return results;
    }

    private static String normalize(String value) {
        if (String.isBlank(value)) {
            return null;
        }
        return value.trim().toLowerCase();
    }
}
