/**
 * Normalizes Contact.Phone values for the dialer: only digits and a single
 * leading '+' are kept (e.g. "+44 (20) 7946-0018" -> "+442079460018").
 */
public with sharing class ContactPhoneCleanup {

    private static final Pattern NOT_DIGIT_OR_PLUS = Pattern.compile('[^0-9+]');

    /**
     * Cleans the Phone of the given contacts and saves them with partial success.
     *
     * @param contactIds up to 200 Contact Ids
     * @return Id of each contact that could not be saved -> its first error message
     *         (empty map when everything was saved)
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
            WITH USER_MODE
        ]) {
            String cleaned = normalize(c.Phone);
            if (cleaned != c.Phone) {
                // Only the Id and the changed field are sent to the database.
                toUpdate.add(new Contact(Id = c.Id, Phone = cleaned));
            }
        }

        if (toUpdate.isEmpty()) {
            return failures;
        }

        // Single DML after the loop; partial success so one invalid record
        // does not block the others. User mode enforces sharing, CRUD and FLS.
        List<Database.SaveResult> results =
            Database.update(toUpdate, false, AccessLevel.USER_MODE);

        // Results come back in the same order as the input list. A failed result
        // has a null getId(), so the Id is taken from the matching contact.
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                List<Database.Error> errors = result.getErrors();
                failures.put(
                    toUpdate[i].Id,
                    errors.isEmpty() ? 'Unknown error' : errors[0].getMessage()
                );
            }
        }
        return failures;
    }

    /**
     * Keeps only digits, plus one '+' if the number starts with one.
     */
    @TestVisible
    private static String normalize(String phone) {
        String stripped = NOT_DIGIT_OR_PLUS.matcher(phone.trim()).replaceAll('');
        Boolean leadingPlus = stripped.startsWith('+');
        String digitsOnly = stripped.replace('+', '');
        return leadingPlus ? '+' + digitsOnly : digitsOnly;
    }
}
