/**
 * Pipeline totals for the weekly sales-ops call.
 *
 * Uses a single grouped aggregate query (rather than one query per stage) so the
 * method consumes one SOQL query regardless of how many stages are reported,
 * leaving query budget for callers and staying correct if the stage list grows.
 *
 * Runs with sharing and in user mode: totals only include opportunities the
 * running user can see, and object/field-level security is enforced.
 */
public with sharing class PipelineSummary {

    /** The open stages managed by sales ops, in reporting order. */
    @TestVisible
    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the sum of Opportunity.Amount per managed stage for opportunities whose
     * CloseDate falls between fromDate and toDate (both inclusive).
     *
     * The map always contains exactly the four managed stages. Stages without matching
     * opportunities map to 0, and opportunities without an Amount contribute nothing.
     *
     * @param fromDate start of the CloseDate range (inclusive), required
     * @param toDate   end of the CloseDate range (inclusive), required
     * @return stage name to total Amount; never contains null values
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException('fromDate and toDate are both required.');
        }

        // Pre-populate every stage with 0 so the result is complete and null-free.
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : STAGES) {
            totals.put(stage, 0);
        }

        // An inverted range cannot match anything; skip the query.
        if (fromDate > toDate) {
            return totals;
        }

        for (AggregateResult row : [
            SELECT StageName stage, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :STAGES
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stage = (String) row.get('stage');
            Decimal total = (Decimal) row.get('total');
            // SUM returns null when every Amount in the group is null.
            if (stage != null && totals.containsKey(stage) && total != null) {
                totals.put(stage, total);
            }
        }

        return totals;
    }
}
