/**
 * Sets Priority = 'High' on new cases whose account has Rating = 'Hot'.
 * All other cases keep the Priority they were created with, including cases
 * without an account.
 *
 * Bulk-safe: it runs at most 2 queries per trigger run, no matter how many
 * cases come in (1 from Email-to-Case or 200 from the ERP integration).
 *
 * "without sharing" is on purpose. This is an org-wide routing rule. It must
 * work the same way even if the user who creates the case (for example the
 * ERP integration user or the Email-to-Case user) cannot see the account.
 * The class only reads the account's Rating and only changes Case.Priority.
 */
public without sharing class CasePriorityHandler {

    @TestVisible
    private static final String HOT_RATING = 'Hot';

    @TestVisible
    private static final String HIGH_PRIORITY = 'High';

    /**
     * Call from the before insert trigger. It changes the records directly,
     * so no DML is needed.
     */
    public static void setPriorityFromAccountRating(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        // Step 1: some cases (often Email-to-Case) only have a Contact.
        // For those, use the contact's account.
        Set<Id> contactIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId == null && c.ContactId != null) {
                contactIds.add(c.ContactId);
            }
        }

        Map<Id, Id> accountIdByContactId = new Map<Id, Id>();
        if (!contactIds.isEmpty()) {
            for (Contact con : [
                SELECT Id, AccountId
                FROM Contact
                WHERE Id IN :contactIds AND AccountId != null
            ]) {
                accountIdByContactId.put(con.Id, con.AccountId);
            }
        }

        // Step 2: collect the account Ids of all the new cases.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            Id accountId = resolveAccountId(c, accountIdByContactId);
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }

        if (accountIds.isEmpty()) {
            return; // No case has an account, so nothing changes.
        }

        // Step 3: ONE query for all the accounts. It returns only the Hot ones.
        Set<Id> hotAccountIds = new Map<Id, Account>([
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds AND Rating = :HOT_RATING
        ]).keySet();

        if (hotAccountIds.isEmpty()) {
            return;
        }

        // Step 4: set High priority on the cases of Hot accounts.
        // Every other case is left exactly as it was created.
        for (Case c : newCases) {
            Id accountId = resolveAccountId(c, accountIdByContactId);
            if (accountId != null && hotAccountIds.contains(accountId)) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }

    /**
     * Returns the case's AccountId. If that is empty, returns the account of
     * the case's contact. Returns null if neither is set.
     */
    private static Id resolveAccountId(Case c, Map<Id, Id> accountIdByContactId) {
        if (c.AccountId != null) {
            return c.AccountId;
        }
        if (c.ContactId != null) {
            return accountIdByContactId.get(c.ContactId);
        }
        return null;
    }
}
```

**What I did differently and why**

1. **No query inside the for loop.** Salesforce allows at most 100 queries in one transaction.
