/**
 * Publishes Deal_Stage_Change__e platform events (publish after commit) for opportunities.
 *
 * All events are published with ONE EventBus.publish call. For publish-after-commit
 * events, each EventBus.publish call counts as a DML statement (limit 150 per
 * transaction). Calling it per record would exceed that limit for a 200-record
 * trigger batch. The bulk call still returns one SaveResult per event, in input
 * order, so each result maps to the opportunity at the same index.
 */
public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per opportunity.
     *
     * @param opportunities opportunities to publish (should have Ids, e.g. after insert/update)
     * @return publish results in the same order as the input list; empty list for null/empty input
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id == null ? null : String.valueOf(opp.Id), // 18-char Id
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            ));
        }

        // Single publish call = single DML statement; returns one SaveResult per event,
        // in the same order as the events list (and therefore the input list).
        results.addAll(EventBus.publish(events));
        return results;
    }
}
