/**
 * Creates follow-up Tasks for opportunities coming out of the weekly pipeline review.
 *
 * Uses a single partial-success insert (allOrNone = false) instead of one DML per task.
 * A task rejected by a validation rule does not block the others, and the call stays
 * within the 150-DML-statement governor limit no matter how many opportunities are passed.
 */
public with sharing class FollowUpTaskService {

    @TestVisible
    private static final String SUBJECT_PREFIX = 'Follow up: ';
    @TestVisible
    private static final String STATUS_NOT_STARTED = 'Not Started';
    @TestVisible
    private static final String PRIORITY_NORMAL = 'Normal';
    @TestVisible
    private static final Integer DAYS_UNTIL_DUE = 7;

    /**
     * Creates one follow-up Task per opportunity.
     *
     * @param opportunityIds Ids of the opportunities to follow up on. Nulls and duplicates are ignored.
     * @return Ids of the opportunities whose task could not be created. This includes
     *         opportunities that were rejected on insert and Ids that do not resolve to an
     *         opportunity visible to the running user. Returns an empty set when every task
     *         was created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Remove nulls and duplicates so each opportunity gets exactly one task.
        Set<Id> requestedIds = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null) {
                requestedIds.add(oppId);
            }
        }
        if (requestedIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // One query for all opportunities. It respects the running user's sharing, CRUD and FLS.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :requestedIds
            WITH USER_MODE
        ];

        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);
        List<Task> tasksToInsert = new List<Task>();
        // Parallel list: the task at index i belongs to the opportunity at index i.
        List<Id> opportunityIdByIndex = new List<Id>();
        Set<Id> foundIds = new Set<Id>();

        for (Opportunity opp : opportunities) {
            foundIds.add(opp.Id);
            tasksToInsert.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = SUBJECT_PREFIX + opp.Name,
                ActivityDate = dueDate,
                Status       = STATUS_NOT_STARTED,
                Priority     = PRIORITY_NORMAL
            ));
            opportunityIdByIndex.add(opp.Id);
        }

        // Ids that were not found (deleted, not visible, or not an Opportunity Id) cannot get a task.
        for (Id requestedId : requestedIds) {
            if (!foundIds.contains(requestedId)) {
                failedOpportunityIds.add(requestedId);
            }
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        // A single DML statement with partial success. Rejected rows are reported in the
        // SaveResults and do not roll back the successful ones.
        List<Database.SaveResult> results =
            Database.insert(tasksToInsert, false, AccessLevel.USER_MODE);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                Id oppId = opportunityIdByIndex[i];
                failedOpportunityIds.add(oppId);
                for (Database.Error err : result.getErrors()) {
                    System.debug(LoggingLevel.WARN,
                        'Follow-up task not created for Opportunity ' + oppId + ': '
                        + err.getStatusCode() + ' - ' + err.getMessage()
                        + ' (fields: ' + err.getFields() + ')');
                }
            }
        }

        return failedOpportunityIds;
    }
}
