/**
 * Keeps Account.Rating in sync with the account's open pipeline.
 * Collects the affected Account Ids for the whole trigger chunk and hands them
 * to AccountRatingService in a single call (one future call per transaction,
 * not one per opportunity, to stay within the 50 future-calls limit).
 */
trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert || Trigger.isUndelete) {
        for (Opportunity opp : Trigger.new) {
            accountIds.add(opp.AccountId);
        }
    } else if (Trigger.isUpdate) {
        for (Opportunity opp : Trigger.new) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
            if (opp.StageName != oldOpp.StageName
                    || opp.Amount != oldOpp.Amount
                    || opp.AccountId != oldOpp.AccountId) {
                accountIds.add(opp.AccountId);
                accountIds.add(oldOpp.AccountId); // previous account may need downgrading
            }
        }
    } else if (Trigger.isDelete) {
        for (Opportunity opp : Trigger.old) {
            accountIds.add(opp.AccountId);
        }
    }

    accountIds.remove(null);

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculateAccounts(accountIds);
    }
}
