/**
 * Calculates Account.Rating from the account's open opportunities:
 *   Hot  - at least one open opportunity with Amount >= 100,000
 *   Warm - open opportunities exist, but none that large
 *   Cold - no open opportunities
 *
 * Runs without sharing on purpose: the rating must reflect ALL open opportunities
 * on the account, not only those visible to the user who saved an opportunity.
 */
public without sharing class AccountRatingService {

    public static final Decimal HOT_THRESHOLD = 100000;
    public static final String RATING_HOT = 'Hot';
    public static final String RATING_WARM = 'Warm';
    public static final String RATING_COLD = 'Cold';

    /**
     * Entry point for the trigger. Recalculates asynchronously where possible,
     * and falls back to synchronous processing where a future call is not allowed
     * (already in a future/batch context, or the future-call limit is exhausted).
     */
    public static void recalculateAccounts(Set<Id> accountIds) {
        Set<Id> ids = cleanIds(accountIds);
        if (ids.isEmpty()) {
            return;
        }

        Boolean canCallFuture = !System.isFuture()
            && !System.isBatch()
            && Limits.getFutureCalls() < Limits.getLimitFutureCalls();

        if (canCallFuture) {
            recalculate(ids);
        } else {
            recalculateNow(ids);
        }
    }

    /**
     * Asynchronous recalculation. Accepts a set so a whole trigger chunk
     * (e.g. 200 CPQ opportunities) is handled by a single future call.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateNow(accountIds);
    }

    /**
     * Synchronous, bulk-safe recalculation: one aggregate query, one account query,
     * and one DML statement regardless of how many accounts are passed in.
     */
    public static void recalculateNow(Set<Id> accountIds) {
        Set<Id> ids = cleanIds(accountIds);
        if (ids.isEmpty()) {
            return;
        }

        // Highest open Amount per account (accounts without open opps are absent).
        // MAX ignores null amounts, so an account whose open opps all lack an Amount
        // still appears here with a null max and is rated Warm.
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();
        for (AggregateResult ar : [
                SELECT AccountId accId, MAX(Amount) maxAmount
                FROM Opportunity
                WHERE AccountId IN :ids
                    AND IsClosed = false
                GROUP BY AccountId]) {
            maxOpenAmountByAccount.put((Id) ar.get('accId'), (Decimal) ar.get('maxAmount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [SELECT Id, Rating FROM Account WHERE Id IN :ids]) {
            String newRating = calculateRating(
                maxOpenAmountByAccount.containsKey(acc.Id),
                maxOpenAmountByAccount.get(acc.Id)
            );
            if (acc.Rating != newRating) {
                accountsToUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        // Partial success: one account failing validation must not block the others.
        List<Database.SaveResult> results = Database.update(accountsToUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'AccountRatingService: failed to update Account '
                        + accountsToUpdate[i].Id + ': '
                        + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
    }

    @TestVisible
    private static String calculateRating(Boolean hasOpenOpportunities, Decimal maxOpenAmount) {
        if (!hasOpenOpportunities) {
            return RATING_COLD;
        }
        if (maxOpenAmount != null && maxOpenAmount >= HOT_THRESHOLD) {
            return RATING_HOT;
        }
        return RATING_WARM;
    }

    private static Set<Id> cleanIds(Set<Id> accountIds) {
        Set<Id> ids = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        ids.remove(null);
        return ids;
    }
}
