/**
 * Matches in-memory Leads to in-memory Contacts by email address.
 *
 * Design note: a nested loop (for each lead, scan all contacts) is O(leads x contacts),
 * i.e. up to ~9 million normalized string comparisons for 3,000 x 3,000 records. That
 * risks the synchronous Apex CPU time limit inside the import transaction. Instead, we
 * index the contacts once in a Map keyed by normalized email (O(contacts)), then do one
 * constant-time lookup per lead (O(leads)).
 *
 * This class performs no SOQL and no DML.
 */
public with sharing class LeadContactMatcher {

    /**
     * For each lead, returns the Id of the first contact (in the order of {@code contacts})
     * whose email matches the lead's email, ignoring case and leading/trailing whitespace.
     * Leads or contacts with a blank email never match.
     *
     * @param leads    leads to match; the result has the same size and order
     * @param contacts candidate contacts; earlier entries win when emails are duplicated
     * @return list of Contact Ids (or null where no match), aligned with {@code leads}
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Index contacts by normalized email, keeping only the first occurrence.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                if (c == null) {
                    continue;
                }
                String key = normalize(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // One lookup per lead; preserves size and order of the input list.
        for (Lead l : leads) {
            String key = (l == null) ? null : normalize(l.Email);
            result.add(key == null ? null : contactIdByEmail.get(key));
        }
        return result;
    }

    /**
     * Normalizes an email for comparison: trims surrounding whitespace and lower-cases it.
     * Returns null for null/blank values so they never match.
     */
    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
