/**
 * When an Account's BillingCountry changes, moves its Contacts along:
 * contacts whose MailingCountry is blank or equal to the account's previous
 * BillingCountry get the new BillingCountry. All other contacts are untouched.
 *
 * Runs without sharing on purpose: this is data-consistency logic and must
 * update every affected contact, regardless of the editing user's visibility.
 */
public without sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldMap == null) {
            return;
        }

        // 1. Determine which accounts actually changed BillingCountry (no queries).
        Map<Id, Account> changedAccounts = new Map<Id, Account>(); // Id -> Trigger.new record
        Set<String> previousCountries = new Set<String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }
            if (hasChanged(oldAcc.BillingCountry, acc.BillingCountry)) {
                changedAccounts.put(acc.Id, acc);
                if (String.isNotBlank(oldAcc.BillingCountry)) {
                    previousCountries.add(oldAcc.BillingCountry);
                }
            }
        }

        if (changedAccounts.isEmpty()) {
            return;
        }

        // 2. One selective query: only contacts of changed accounts that could match.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccounts.keySet()
              AND (MailingCountry = null OR MailingCountry IN :previousCountries)
        ]) {
            String oldCountry = oldMap.get(c.AccountId).BillingCountry;
            String newCountry = changedAccounts.get(c.AccountId).BillingCountry;

            // Re-check per account: the IN filter covers old countries of all accounts in the batch.
            Boolean isBlank = String.isBlank(c.MailingCountry);
            Boolean matchesOld = String.isNotBlank(oldCountry) && c.MailingCountry == oldCountry; // case-insensitive, like SOQL
            if (!isBlank && !matchesOld) {
                continue; // works abroad - leave alone
            }

            // Skip no-op updates.
            if (!hasChanged(c.MailingCountry, newCountry)) {
                continue;
            }

            contactsToUpdate.add(new Contact(Id = c.Id, AccountId = c.AccountId, MailingCountry = newCountry));
        }

        if (contactsToUpdate.isEmpty()) {
            return;
        }

        // 3. Partial-success DML; surface failures on the owning account only.
        List<Contact> dmlRecords = new List<Contact>();
        for (Contact c : contactsToUpdate) {
            // Only send the fields we intend to change.
            dmlRecords.add(new Contact(Id = c.Id, MailingCountry = c.MailingCountry));
        }

        List<Database.SaveResult> results = Database.update(dmlRecords, false);
        Set<Id> accountsWithErrors = new Set<Id>();
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (sr.isSuccess()) {
                continue;
            }
            Id accountId = contactsToUpdate[i].AccountId;
            if (accountsWithErrors.contains(accountId)) {
                continue; // one error message per account is enough
            }
            accountsWithErrors.add(accountId);

            String message = sr.getErrors().isEmpty()
                ? 'Unknown error'
                : sr.getErrors()[0].getMessage();
            changedAccounts.get(accountId).addError(
                'Could not update MailingCountry on related contact ' +
                contactsToUpdate[i].Id + ': ' + message
            );
        }
    }

    /**
     * Case-sensitive change check that treats null and blank as equal.
     */
    @TestVisible
