```javascript
import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD, ANNUAL_REVENUE_FIELD, OWNER_NAME_FIELD];

/**
 * Reads a (possibly spanning) field value from a UI API record representation.
 * Example path: ['Owner', 'Name'] -> record.fields.Owner.value.fields.Name.value
 */
function readField(record, path) {
    let current = record;
    for (let i = 0; i < path.length; i++) {
        if (!current || !current.fields) {
            return undefined;
        }
        const field = current.fields[path[i]];
        if (field === undefined || field === null) {
            return undefined;
        }
        current = field.value;
        if (i < path.length - 1 && (current === null || current === undefined)) {
            return undefined;
        }
    }
    return current;
}

export default class AccountHeader extends LightningElement {
    // Provided by the record page. Used reactively ('$recordId') in the wire below,
    // so a new value (e.g. reused console tab) re-provisions the wire automatically.
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        } else {
            this.record = undefined;
            this.error = undefined;
        }
    }

    get hasError() {
        return !!this.error;
    }

    get hasData() {
        return !this.error && !!this.record;
    }

    get errorMessage() {
        const err = this.error;
        if (!err) {
            return '';
        }
        if (err.body) {
            if (Array.isArray(err.body)) {
                return err.body.map((e) => e.message).join(', ');
            }
            if (err.body.message) {
                return err.body.message;
            }
        }
        return err.message || 'Unknown error';
    }

    get name() {
        return readField(this.record, ['Name']);
    }

    get industry() {
        return readField(this.record, ['Industry']);
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return readField(this.record, ['AnnualRevenue']);
    }

    get ownerName() {
        return readField(this.record, ['Owner', 'Name']);
    }
}
