import { LightningElement, api } from 'lwc';

const THEME_BY_STATUS = {
    New: 'slds-theme_info',
    Escalated: 'slds-theme_error',
    Closed: 'slds-theme_success'
};

export default class CaseStatusBadge extends LightningElement {
    /**
     * Case status supplied by the parent component.
     * Do not cache derived values from it; parents can change it at any time.
     */
    @api status;

    /**
     * True when status has a value (not empty string, null or undefined).
     */
    get hasStatus() {
        return this.status !== undefined && this.status !== null && this.status !== '';
    }

    /**
     * Badge CSS classes for the current status.
     * Recomputed on every render, so it always matches the latest status.
     */
    get badgeClass() {
        const theme = Object.prototype.hasOwnProperty.call(THEME_BY_STATUS, this.status)
            ? THEME_BY_STATUS[this.status]
            : null;
        return theme ? `slds-badge ${theme}` : 'slds-badge';
    }
}
