```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    results = [];
    errorMessage;

    // Handle of the pending debounce timer (null when nothing is scheduled).
    _debounceTimer = null;
    // Latest trimmed search term typed by the user.
    _latestTerm = '';
    // Increases with every request (and every invalidation). A response is
    // applied only if its id still matches this value.
    _requestSequence = 0;

    get hasResults() {
        return Array.isArray(this.results) && this.results.length > 0;
    }

    get hasError() {
        return !!this.errorMessage;
    }

    handleSearchChange(event) {
        const rawValue =
            event.detail && event.detail.value !== undefined
                ? event.detail.value
                : event.target.value;
        const term = (rawValue ?? '').toString().trim();
        this._latestTerm = term;

        // Cancel any search that is still waiting for the debounce delay.
        this._clearPendingSearch();

        if (term.length < MIN_SEARCH_LENGTH) {
            // Invalidate any in-flight request so a late response cannot
            // repopulate the results.
            this._requestSequence++;
            this.results = [];
            this.errorMessage = undefined;
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._runSearch(this._latestTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    disconnectedCallback() {
        // Make sure a pending search never runs after the component is removed,
        // and ignore responses to requests that are already in flight.
        this._clearPendingSearch();
        this._requestSequence++;
    }

    async _runSearch(searchTerm) {
        const requestId = ++this._requestSequence;
        try {
            const data = await searchContacts({ searchTerm });
            if (requestId !== this._requestSequence) {
                return; // stale response
            }
            this.results = Array.isArray(data) ? data : [];
            this.errorMessage = undefined;
        } catch (error) {
            if (requestId !== this._requestSequence) {
                return; // stale error
            }
            this.results = [];
            this.errorMessage = this._reduceError(error);
        }
    }

    _clearPendingSearch() {
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
    }

    _reduceError(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }
}
