import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    opportunities = [];
    errorMessage;
    hasError = false;
    isLoading = false;

    _initialized = false;

    connectedCallback() {
        // Load exactly once, even if the component is removed and reinserted
        if (!this._initialized) {
            this._initialized = true;
            this.loadOpportunities();
        }
    }

    async loadOpportunities() {
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = undefined;
        try {
            const result = await getOpenOpportunities({ accountId: this.recordId });
            this.opportunities = Array.isArray(result) ? result : [];
        } catch (error) {
            this.opportunities = [];
            this.errorMessage = this.reduceError(error);
            this.hasError = true;
        } finally {
            this.isLoading = false;
        }
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }

    reduceError(error) {
        if (!error) {
            return 'Unknown error';
        }
        const body = error.body;
        if (body) {
            if (typeof body.message === 'string') {
                return body.message;
            }
            if (Array.isArray(body)) {
                return body.map((e) => e && e.message).filter(Boolean).join(', ');
            }
        }
        if (typeof error.message === 'string') {
            return error.message;
        }
        return 'Unknown error';
    }
}
