import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines;

    showError = false;

    get lineItems() {
        return Array.isArray(this.lines) ? this.lines : [];
    }

    get editors() {
        // querySelectorAll returns elements in DOM (display) order
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.editors;

        // Validate every editor (no short-circuit) so all errors are shown at once
        let allValid = true;
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const lines = editors.map((editor) => editor.getValue());
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines }
            })
        );
    }
}
