```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;

    _intervalId = null;
    _inFlight = false;
    _connected = false;
    // Increases on every insert/remove. A response that comes back after the
    // component was removed (or removed and inserted again) is ignored.
    _generation = 0;

    get hasError() {
        return !!this.errorMessage;
    }

    connectedCallback() {
        this._connected = true;
        this._generation += 1;
        this._inFlight = false;
        document.addEventListener('visibilitychange', this._handleVisibilityChange);
        if (!this._isHidden()) {
            this._loadStats();
            this._startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        this._generation += 1;
        this._inFlight = false;
        this._stopPolling();
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);
    }

    // Arrow function so the same reference is used to add and remove the listener.
    _handleVisibilityChange = () => {
        if (!this._connected) {
            return;
        }
        if (this._isHidden()) {
            this._stopPolling();
        } else {
            this._loadStats();
            this._startPolling();
        }
    };

    _isHidden() {
        return document.visibilityState === 'hidden';
    }

    _startPolling() {
        // Only one polling loop at a time.
        this._stopPolling();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this._loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    _loadStats() {
        // Skip if removed, hidden, or a request is still running.
        if (!this._connected || this._isHidden() || this._inFlight) {
            return;
        }
        this._inFlight = true;
        const generation = this._generation;

        getQueueStats()
            .then((result) => {
                if (generation !== this._generation) {
                    return;
                }
                this.waiting = result ? result.waiting : undefined;
                this.longestWaitMinutes = result ? result.longestWaitMinutes : undefined;
                this.hasStats = true;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (generation !== this._generation) {
                    return;
                }
                this.errorMessage = this._reduceError(error);
            })
            .finally(() => {
                if (generation === this._generation) {
                    this._inFlight = false;
                }
            });
    }

    _reduceError(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }
}
