import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_DOMAINS = new Set(['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com']);
const WORK_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName;
    email;
    company;
    isSubmitting = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    static extractDomain(email) {
        if (typeof email !== 'string') {
            return '';
        }
        const atIndex = email.lastIndexOf('@');
        if (atIndex === -1) {
            return '';
        }
        return email.substring(atIndex + 1).trim().toLowerCase();
    }

    async handleRegister() {
        if (this.isSubmitting) {
            return;
        }

        // Step 1: work email check, before reporting validity.
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            const domain = EventRegistrationForm.extractDomain(this.email);
            if (BLOCKED_DOMAINS.has(domain)) {
                emailInput.setCustomValidity(WORK_EMAIL_MESSAGE);
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // Step 2: report validity on every input (no short-circuit).
        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const allValid = inputs.reduce((valid, input) => {
            const inputValid = input.reportValidity();
            return valid && inputValid;
        }, true);

        // Step 3: stop if anything is invalid.
        if (!allValid) {
            return;
        }

        this.isSubmitting = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    message: 'You are registered for the event.',
                    variant: 'success'
                })
            );
        } catch (error) {
            const message =
                error && error.body && error.body.message
                    ? error.body.message
                    : 'An unexpected error occurred.';
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message,
                    variant: 'error'
                })
            );
        } finally {
            this.isSubmitting = false;
        }
    }
}
