import { LightningElement, api } from 'lwc';

const ID_PREFIX = 'status-option-';

export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox (rendered as aria-label). */
    @api label;

    _options = [];
    _value;
    activeIndex = 0;
    _scrollPending = false;

    /** Array of { value, label }. */
    @api
    get options() {
        return this._options;
    }
    set options(newOptions) {
        // Never mutate the (read-only) array passed by the parent.
        this._options = Array.isArray(newOptions)
            ? newOptions.filter((option) => option !== null && option !== undefined)
            : [];
        this._syncActiveToSelection();
    }

    /** Selected value; may be changed by the parent at any time. */
    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue;
        const selected = this.selectedIndex;
        if (selected !== -1) {
            // Parent changed the selection: the active option follows it.
            this.activeIndex = selected;
        } else {
            this._clampActiveIndex();
        }
    }

    get selectedIndex() {
        return this._options.findIndex((option) => option.value === this._value);
    }

    get activeId() {
        return this._options.length > 0 ? this._idFor(this.activeIndex) : null;
    }

    get renderedOptions() {
        const selected = this.selectedIndex;
        return this._options.map((option, index) => {
            const isSelected = index === selected;
            const isActive = index === this.activeIndex;
            let className = 'slds-listbox__item slds-p-horizontal_small slds-p-vertical_x-small';
            if (isActive) {
                className += ' slds-has-focus slds-theme_shade';
            }
            if (isSelected) {
                className += ' slds-is-selected slds-text-title_bold';
            }
            return {
                id: this._idFor(index),
                index,
                value: option.value,
                label: option.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className
            };
        });
    }

    handleKeyDown(event) {
        const lastIndex = this._options.length - 1;
        let nextIndex;

        switch (event.key) {
            case 'ArrowDown':
                nextIndex = Math.min(this.activeIndex + 1, lastIndex);
                break;
            case 'ArrowUp':
                nextIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                nextIndex = 0;
                break;
            case 'End':
                nextIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectIndex(this.activeIndex);
                return;
            default:
                // Every other key (e.g. Tab) keeps its default behaviour.
                return;
        }

        event.preventDefault();
        if (lastIndex < 0) {
            return;
        }
        if (nextIndex !== this.activeIndex) {
            this.activeIndex = nextIndex;
            this._scrollPending = true;
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (Number.isNaN(index) || index < 0 || index >= this._options.length) {
            return;
        }
        this.activeIndex = index;
        this._selectIndex(index);
    }

    renderedCallback() {
        if (!this._scrollPending) {
            return;
        }
        this._scrollPending = false;
        const activeElement = this.template.querySelector(
            `li[data-index="${this.activeIndex}"]`
        );
        if (activeElement && typeof activeElement.scrollIntoView === 'function') {
            activeElement.scrollIntoView({ block: 'nearest' });
        }
    }

    _selectIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            // Already selected: nothing to dispatch.
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }

    _syncActiveToSelection() {
        const selected = this.selectedIndex;
        this.activeIndex = selected !== -1 ? selected : 0;
    }

    _clampActiveIndex() {
        if (this.activeIndex < 0 || this.activeIndex >= this._options.length) {
            this.activeIndex = 0;
        }
    }

    _idFor(index) {
        // Index-based ids are always valid, even if option values contain spaces.
        return `${ID_PREFIX}${index}`;
    }
}
