```javascript
import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Display-only public property: never reassigned by the component.
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        // Work on our own copy: new array and new task objects, so the
        // parent's data is never modified.
        this.items = Array.isArray(value)
            ? value.map((task) => ({
                  id: task.id,
                  label: task.label,
                  done: !!task.done
              }))
            : [];
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        const value =
            event.detail && event.detail.value !== undefined
                ? event.detail.value
                : event.target.value;
        this.newLabel = value == null ? '' : String(value);
    }

    generateId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (existing.has(id));
        return id;
    }

    handleAdd() {
        const input = this.template.querySelector('lightning-input.new-task');
        let raw = this.newLabel;
        if (!raw && input && input.value) {
            raw = input.value;
        }
        const label = raw == null ? '' : String(raw).trim();
        if (!label) {
            return;
        }

        this.items = [...this.items, { id: this.generateId(), label, done: false }];

        // Clear the input.
        this.newLabel = '';
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.currentTarget.dataset.id;
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
