```apex
/**
 * Records monthly giving sign-ups from the donation form as NPSP
 * Enhanced Recurring Donations (ERD).
 *
 * Design notes:
 *  - Only ERD fields are populated: RecurringType, InstallmentFrequency,
 *    Day_of_Month, StartDate and Status. The legacy fields (Schedule_Type,
 *    Open_Ended_Status, Next_Payment_Date, Always_Use_Last_Day_Of_Month)
 *    are left for NPSP to manage.
 *  - The form's "31" is stored as ERD's 'Last_Day' Day of Month picklist value.
 *  - No Opportunities are created here. NPSP's recurring donation triggers
 *    generate the installment opportunities themselves.
 *  - Bulk-safe: no SOQL and exactly one DML statement per call.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    // ERD picklist / constant values (match NPSP's RD2_Constants)
    @TestVisible private static final String RECURRING_TYPE_OPEN = 'Open';
    @TestVisible private static final String RECURRING_TYPE_FIXED = 'Fixed';
    @TestVisible private static final String PERIOD_MONTHLY = 'Monthly';
    @TestVisible private static final String STATUS_ACTIVE = 'Active';
    @TestVisible private static final String DAY_OF_MONTH_LAST_DAY = 'Last_Day';
    @TestVisible private static final Integer LAST_DAY_FORM_VALUE = 31;

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new
     * record Ids in the same order as the requests.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // Validate everything before any DML
        validate(requests);

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            donations.add(buildRecurringDonation(req));
        }

        // Single DML statement, enforcing the running user's CRUD/FLS and sharing.
        // allOrNone = true, so the whole batch rolls back on any failure.
        Database.insert(donations, true, AccessLevel.USER_MODE);

        for (npe03__Recurring_Donation__c rd : donations) {
            result.add(rd.Id);
        }
        return result;
    }

    private static void validate(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            String prefix = 'Request ' + (i + 1) + ': ';

            if (req == null) {
                throw new RecurringGiftException(prefix + 'request is null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException(prefix + 'contact is required.');
            }
            if (req.contactId.getSObjectType() != Contact.SObjectType) {
                throw new RecurringGiftException(prefix + 'contactId must be a Contact Id.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(prefix + 'amount must be greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(prefix + 'dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(prefix + 'startDate is required.');
            }
            if (req.installments != null && req.installments < 0) {
                throw new RecurringGiftException(prefix + 'installments cannot be negative.');
            }
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        Boolean isOpenEnded = (req.installments == null || req.installments == 0);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
            npe03__Contact__c = req.contactId,
            npe03__Amount__c = req.amount,
            npe03__Installment_Period__c = PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c = 1,
            npsp__Day_of_Month__c = toDayOfMonthValue(req.dayOfMonth),
            npsp__StartDate__c = req.startDate,
            npsp__Status__c = STATUS_ACTIVE,
            npsp__PaymentMethod__c = req.paymentMethod
        );

        if (isOpenEnded) {
            rd.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
        } else {
            rd.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            rd.npe03__Installments__c = req.installments;
        }

        return rd;
    }

    /**
