/**
 * Creates or updates NPSP partial soft credits for peer-to-peer fundraisers.
 *
 * For each request the contact ends up with:
 *  - exactly one OpportunityContactRole on the opportunity, whose Role equals the requested role
 *  - exactly one npsp__Partial_Soft_Credit__c on the opportunity, linked to that contact role,
 *    with the requested amount and role name.
 *
 * The whole call is validated before any DML. If any request is invalid, a
 * SoftCreditException is thrown and nothing is changed.
 *
 * Governor usage per call, regardless of size: 3 SOQL queries and at most 3 DML statements.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---------- Basic shape validation (no queries yet) ----------
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            if (req == null) {
                throw new SoftCreditException('Request #' + i + ' is null.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Request #' + i + ' must specify both an opportunity and a contact.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Request #' + i + ' must have a positive soft credit amount.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---------- SOQL 1: opportunities ----------
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // ---------- SOQL 2: existing contact roles ----------
        Map<String, List<OpportunityContactRole>> ocrsByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = buildKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByKey.containsKey(key)) {
                ocrsByKey.put(key, new List<OpportunityContactRole>());
            }
            ocrsByKey.get(key).add(ocr);
        }

        // ---------- SOQL 3: existing partial soft credits ----------
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = buildKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscsByKey.containsKey(key)) {
                pscsByKey.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscsByKey.get(key).add(psc);
        }

        // ---------- Full validation against data, still before any DML ----------
        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            Opportunity opp = oppsById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Request #' + i + ': opportunity ' + req.opportunityId + ' was not found or is not accessible.');
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Request #' + i + ': the primary contact of an opportunity cannot receive a soft credit on it.');
            }
            List<OpportunityContactRole> existingOcrs = ocrsByKey.get(buildKey(req.opportunityId, req.contactId));
            if (existingOcrs != null) {
                for (OpportunityContactRole ocr : existingOcrs) {
                    if (ocr.IsPrimary) {
                        throw new SoftCreditException('Request #' + i + ': the primary contact of an opportunity cannot receive a soft credit on it.');
                    }
                }
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Request #' + i + ': the soft credit amount cannot exceed the opportunity amount.');
            }
        }

        // ---------- Build the changes in memory ----------
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<SObject> recordsToDelete = new List<SObject>();
        List<OpportunityContactRole> keptOcrPerRequest = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> pscPerRequest = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = buildKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> candidates = ocrsByKey.containsKey(key)
                ? ocrsByKey.get(key)
                : new List<OpportunityContactRole>();
            List<npsp__Partial_Soft_Credit__c> existingPscs = pscsByKey.containsKey(key)
                ? pscsByKey.get(key)
                : new List<npsp__Partial_Soft_Credit__c>();

            // Pick the soft credit to keep: prefer one already linked to one of the contact's roles.
            npsp__Partial_Soft_Credit__c keptPsc = null;
            OpportunityContactRole keptOcr = null;
            for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
                OpportunityContactRole linked = findOcr(candidates, psc.npsp__Contact_Role_ID__c);
                if (linked != null) {
                    keptPsc = psc;
                    keptOcr = linked;
                    break;
                }
            }
            if (keptPsc == null && !existingPscs.isEmpty()) {
                keptPsc = existingPscs[0];
            }

            // Pick the contact role to keep if the soft credit did not determine it.
            if (keptOcr == null) {
                for (OpportunityContactRole ocr : candidates) {
                    if (ocr.Role == req.role) {
                        keptOcr = ocr;
                        break;
                    }
                }
            }
            if (keptOcr == null && !candidates.isEmpty()) {
                keptOcr = candidates[0];
            }

            if (keptOcr == null) {
                keptOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToUpsert.add(keptOcr);
            } else if (keptOcr.Role != req.role) {
                keptOcr.Role = req.role;
                ocrsToUpsert.add(keptOcr);
            }

            // Any other contact roles for this contact on this opportunity are removed.
            for (OpportunityContactRole ocr : candidates) {
                if (ocr !== keptOcr) {
                    recordsToDelete.add(ocr);
                }
            }

            // Any duplicate soft credits for this contact on this opportunity are removed.
            for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
                if (psc !== keptPsc) {
                    recordsToDelete.add(psc);
                }
            }

            if (keptPsc == null) {
                keptPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            }
            keptPsc.npsp__Amount__c = req.amount;
            keptPsc.npsp__Role_Name__c = req.role;

            keptOcrPerRequest.add(keptOcr);
            pscPerRequest.add(keptPsc);
        }

        // ---------- DML (all or nothing) ----------
        Savepoint sp = Database.setSavepoint();
        try {
            // DML 1: create new / update changed contact roles
            if (!ocrsToUpsert.isEmpty()) {
                upsert ocrsToUpsert;
            }

            // Link each soft credit to its (now persisted) contact role
            for (Integer i = 0; i < pscPerRequest.size(); i++) {
                pscPerRequest[i].npsp__Contact_Role_ID__c = keptOcrPerRequest[i].Id;
            }

            // DML 2: create new / update existing partial soft credits
            upsert pscPerRequest;

            // DML 3: remove surplus contact roles and duplicate soft credits
            if (!recordsToDelete.isEmpty()) {
                delete sortByType(recordsToDelete);
            }
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    private static String buildKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }

    /** Finds the contact role whose Id matches a text Id (15- or 18-character). */
    private static OpportunityContactRole findOcr(List<OpportunityContactRole> ocrs, String ocrIdText) {
        if (String.isBlank(ocrIdText)) {
            return null;
        }
        Id ocrId;
        try {
            ocrId = Id.valueOf(ocrIdText.trim());
        } catch (Exception e) {
            return null;
        }
        for (OpportunityContactRole ocr : ocrs) {
            if (ocr.Id == ocrId) {
                return ocr;
            }
        }
        return null;
    }

    /** Groups records by sObject type so a mixed-type delete uses as few chunks as possible. */
    private static List<SObject> sortByType(List<SObject> records) {
        List<SObject> ocrs = new List<SObject>();
        List<SObject> others = new List<SObject>();
        for (SObject rec : records) {
            if (rec instanceof OpportunityContactRole) {
                ocrs.add(rec);
            } else {
                others.add(rec);
            }
        }
        List<SObject> result = new List<SObject>();
        result.addAll(others);
        result.addAll(ocrs);
        return result;
    }
}
```

**Design notes**

- **Limits:** The class uses 3 SOQL queries, one each for opportunities, contact roles and partial soft credits. It uses at most 3 DML statements, no matter how many requests there are:
  1. upsert contact roles,
  2. upsert soft credits,
  3. one delete for mixed record types.
- **Validation before any DML:** Every request is checked before anything is written:
  - the opportunity and contact are present,
  - the amount is not null and is positive,
  - the opportunity exists,
  - the contact is not `npsp__Primary_Contact__c`,
  - the amount is not more than the opportunity amount.
  - The class also rejects a contact that holds an `IsPrimary` contact role. It treats an opportunity with a null Amount as invalid. If any check fails, the whole call throws `SoftCreditException` and nothing is changed.
- **Exactly one contact role:** The class keeps one existing contact role, chosen in this order:
  1. the role an existing soft credit already points to,
  2. otherwise a role that already matches the requested role,
  3. otherwise the oldest role.
  - It sets that role's `Role` to the requested value, or creates a new contact role if none exists. Any other contact roles for that contact on that opportunity, such as NPSP's `Household Member`, are deleted.
- **No duplicate soft credits:** An existing soft credit is updated with the new amount, role name and `npsp__Contact_Role_ID__c`. Any extra duplicates are deleted. The deletes run only after the soft credits have been re-linked to the kept contact role.
- **Contact name field:** `npsp__Contact_Name__c` is never written to.
- **All or nothing:** The DML runs inside a savepoint, so a failure partway through leaves no partial changes.

