/**
 * Records gifts that have already been received, crediting them the way NPSP expects
 * (Household Account model, NPSP Payments enabled).
 *
 * NPSP's own triggers fire when the Opportunity is inserted. Depending on the org's
 * settings, they may already create:
 *  - the primary contact role,
 *  - the Household Member contact roles, and
 *  - an automatic payment for a Closed Won gift.
 *
 * This service does not blindly insert those records, which would create duplicates.
 * Instead it inserts the Opportunity and then reconciles what NPSP produced against
 * the required end state:
 *  - one Donor role (primary) for the donor and one Household Member role for every
 *    other household member;
 *  - no contact holding more than one role on the gift;
 *  - exactly one paid payment for the full amount, dated on the gift date.
 *
 * Everything runs in user mode and inside a savepoint, so a failure leaves no partial data.
 */
public with sharing class GiftService {

    public static final String DONOR_ROLE = 'Donor';
    public static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';
    private static final String DEFAULT_WON_STAGE = 'Closed Won';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInputs(contactId, amount, giftDate);

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not associated with a household account.'
            );
        }

        String oppName = buildOpportunityName(donor, giftDate);

        Savepoint sp = Database.setSavepoint();
        try {
            Opportunity opp = new Opportunity(
                Name = oppName,
                AccountId = donor.AccountId,
                npsp__Primary_Contact__c = donor.Id,
                Amount = amount,
                CloseDate = giftDate,
                StageName = resolveClosedWonStage()
            );
            Database.insert(opp, AccessLevel.USER_MODE);

            enforceOpportunityName(opp.Id, oppName);
            reconcileContactRoles(opp.Id, donor);
            reconcilePayment(opp.Id, amount, giftDate);

            return opp.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    // ------------------------------------------------------------------ validation

    private static void validateInputs(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null || contactId.getSObjectType() != Contact.SObjectType) {
            throw new IllegalArgumentException('A valid Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
    }

    // ------------------------------------------------------------------ naming / stage

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        List<String> parts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            parts.add(donor.FirstName.trim());
        }
        if (String.isNotBlank(donor.LastName)) {
            parts.add(donor.LastName.trim());
        }
        parts.add('Donation');
        // String.valueOf(Date) yields yyyy-MM-dd and is not affected by time zones.
        parts.add(String.valueOf(giftDate));
        return String.join(parts, ' ');
    }

    private static String resolveClosedWonStage() {
        List<OpportunityStage> wonStages = [
            SELECT ApiName
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder
        ];
        if (wonStages.isEmpty()) {
            return DEFAULT_WON_STAGE;
        }
        for (OpportunityStage stage : wonStages) {
            if (stage.ApiName == DEFAULT_WON_STAGE) {
                return stage.ApiName;
            }
        }
        return wonStages[0].ApiName;
    }

    /** NPSP Opportunity Naming may overwrite the name on insert, so the required name is restored. */
    private static void enforceOpportunityName(Id oppId, String requiredName) {
        Opportunity current = [
            SELECT Id, Name
            FROM Opportunity
            WHERE Id = :oppId
            WITH USER_MODE
        ];
        if (current.Name != requiredName) {
            Database.update(new Opportunity(Id = oppId, Name = requiredName), AccessLevel.USER_MODE);
        }
    }

    // ------------------------------------------------------------------ contact roles

    private static void reconcileContactRoles(Id oppId, Contact donor) {
        // The required roles, keyed by contact.
        Map<Id, String> requiredRoles = new Map<Id, String>{ donor.Id => DONOR_ROLE };
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId AND Id != :donor.Id
            WITH USER_MODE
        ]) {
            requiredRoles.put(member.Id, HOUSEHOLD_MEMBER_ROLE);
        }

        // Keep one role per contact. Prefer a role that already matches, then the primary one,
        // then the oldest. Mark every other role for deletion.
        Map<Id, OpportunityContactRole> keptByContact = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            WITH USER_MODE
            ORDER BY IsPrimary DESC, CreatedDate ASC
        ]) {
            OpportunityContactRole kept = keptByContact.get(ocr.ContactId);
            if (kept == null) {
                keptByContact.put(ocr.ContactId, ocr);
                continue;
            }
            String wanted = requiredRoles.get(ocr.ContactId);
            if (wanted != null && kept.Role != wanted && ocr.Role == wanted) {
                toDelete.add(kept);
                keptByContact.put(ocr.ContactId, ocr);
            } else {
                toDelete.add(ocr);
            }
        }

        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        for (Id cId : requiredRoles.keySet()) {
            String role = requiredRoles.get(cId);
            Boolean primary = (cId == donor.Id);
            OpportunityContactRole existing = keptByContact.get(cId);
            if (existing == null) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = cId,
                    Role = role,
                    IsPrimary = primary
                ));
            } else if (existing.Role != role || existing.IsPrimary != primary) {
                toUpdate.add(new OpportunityContactRole(
                    Id = existing.Id,
                    Role = role,
                    IsPrimary = primary
                ));
            }
        }

        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, AccessLevel.USER_MODE);
        }
        if (!toUpdate.isEmpty()) {
            Database.update(toUpdate, AccessLevel.USER_MODE);
        }
        if (!toInsert.isEmpty()) {
            Database.insert(toInsert, AccessLevel.USER_MODE);
        }
    }

    // ------------------------------------------------------------------ payment

    private static void reconcilePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            WITH USER_MODE
            ORDER BY npe01__Paid__c DESC, CreatedDate ASC
        ];

        if (payments.isEmpty()) {
            Database.insert(new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            ), AccessLevel.USER_MODE);
            return;
        }

        // Keep exactly one payment and remove any duplicates first, so that the
        // payment totals never exceed the gift amount.
        npe01__OppPayment__c keep = payments[0];
        List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < payments.size(); i++) {
            extras.add(payments[i]);
        }
        if (!extras.isEmpty()) {
            Database.delete(extras, AccessLevel.USER_MODE);
        }

        if (keep.npe01__Payment_Amount__c != amount
                || keep.npe01__Payment_Date__c != giftDate
                || keep.npe01__Scheduled_Date__c != giftDate
                || keep.npe01__Paid__c != true) {
            Database.update(new npe01__OppPayment__c(
                Id = keep.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            ), AccessLevel.USER_MODE);
        }
    }
}
```

