```apex
/**
 * Determines which records the running user can edit, using the platform's
 * UserRecordAccess object (covers object permissions, ownership, sharing,
 * role hierarchy, View All / Modify All, etc.).
 */
public with sharing class RecordAccessService {

    /** UserRecordAccess accepts at most 200 record IDs per query. */
    @TestVisible
    private static final Integer MAX_IDS_PER_QUERY = 200;

    /**
     * Returns the subset of recordIds the running user has edit access to.
     * Never returns null. IDs may belong to different objects.
     * Uses ceil(n / 200) SOQL queries (10 queries for 2,000 IDs).
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Defensive copy without nulls.
        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }
        if (ids.isEmpty()) {
            return result;
        }

        Id userId = UserInfo.getUserId();
        Integer total = ids.size();

        for (Integer start = 0; start < total; start += MAX_IDS_PER_QUERY) {
            Integer stop = Math.min(start + MAX_IDS_PER_QUERY, total);
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :userId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
```

