File: force-app/main/default/classes/TA_Account_CreateOnboardingTask.cls
```apex
/**
 * Trigger Actions Framework action (Account, After Insert).
 *
 * When an Account is created with Type "Customer - Direct" or "Customer - Channel",
 * this creates an onboarding Task:
 *  - assigned to the Account's owner (not the running user)
 *  - related to the Account
 *  - due in 7 days
 *
 * It runs after insert because the Task's WhatId needs the Account's Id.
 * It is bulk-safe:
 *  - at most one DML statement per trigger execution
 *  - no DML when no Account qualifies
 *
 * Registered via Trigger_Action__mdt.TA_Account_CreateOnboardingTask (After_Insert__c = Account).
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    @TestVisible
    private static final String TASK_SUBJECT = 'Onboard new customer';
    @TestVisible
    private static final String TASK_STATUS = 'Not Started';
    @TestVisible
    private static final String TASK_PRIORITY = 'Normal';
    @TestVisible
    private static final Integer DAYS_UNTIL_DUE = 7;
    @TestVisible
    private static final Set<String> QUALIFYING_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);
        List<Task> tasksToInsert = new List<Task>();

        for (Account acc : (List<Account>) triggerNew) {
            if (acc.Type != null && QUALIFYING_TYPES.contains(acc.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = TASK_SUBJECT,
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = dueDate,
                        Status = TASK_STATUS,
                        Priority = TASK_PRIORITY
                    )
                );
            }
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        // This is required business automation, so it runs in system mode on purpose.
        // Account creation should not fail because the creating user lacks
        // Task create permission or cannot assign tasks to the Account owner.
        // All-or-nothing: if a Task fails to insert, the Account insert is rolled back too.
        Database.insert(tasksToInsert, true, AccessLevel.SYSTEM_MODE);
