```apex
/**
 * Trigger Action (after insert / after update on Opportunity) that collects the Ids of the
 * opportunities that must be pushed to the ERP.
 *
 * The Ids are kept in transaction-static state. A single DML operation can run the trigger in
 * several chunks of up to 200 records, and TAF creates a new action instance for each chunk, so
 * an instance member would not see the whole operation. OpportunityErpSyncFinalizer runs once,
 * at the end of each DML operation. It takes the collected Ids with takePendingIds(), which also
 * resets the state. The next DML statement in the same transaction therefore starts empty.
 */
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    @TestVisible
    private static final String FINALIZER_CLASS_NAME = 'OpportunityErpSyncFinalizer';

    @TestVisible
    private static Set<Id> pendingIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        if (!isCollectionEnabled()) {
            return;
        }
        for (SObject record : triggerNew) {
            pendingIds.add(record.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (!isCollectionEnabled()) {
            return;
        }
        Map<Id, SObject> oldRecordsById = new Map<Id, SObject>(triggerOld);
        for (SObject record : triggerNew) {
            Opportunity newOpportunity = (Opportunity) record;
            Opportunity oldOpportunity = (Opportunity) oldRecordsById.get(newOpportunity.Id);
            if (oldOpportunity != null && stageChanged(newOpportunity.StageName, oldOpportunity.StageName)) {
                pendingIds.add(newOpportunity.Id);
            }
        }
    }

    /**
     * Returns every Id collected since the last call and resets the collection.
     * Called by OpportunityErpSyncFinalizer at the end of each DML operation.
     */
    public static Set<Id> takePendingIds() {
        Set<Id> collected = pendingIds;
        pendingIds = new Set<Id>();
        return collected;
    }

    /**
     * If the finalizer is bypassed for this operation, nothing would consume the Ids.
     * They would then leak into the job of the next DML statement in the transaction,
     * so don't collect them.
     */
    private static Boolean isCollectionEnabled() {
        return !FinalizerHandler.isBypassed(FINALIZER_CLASS_NAME);
    }

    /**
     * Case-sensitive, null-safe comparison. Apex '!=' on Strings ignores case.
     */
    private static Boolean stageChanged(String newStage, String oldStage) {
        if (newStage == null || oldStage == null) {
            return !(newStage == null && oldStage == null);
        }
        return !newStage.equals(oldStage);
    }
}
