/**
 * DML finalizer that enqueues exactly one OpportunityErpSyncJob per DML operation.
 * The job carries every Opportunity Id collected by TA_Opportunity_CollectForErpSync during
 * that operation, across all trigger chunks.
 *
 * TAF calls every finalizer at the end of every DML operation it handles, on any sObject. When
 * nothing was collected this finalizer does nothing. It performs no DML.
 */
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    public void execute(FinalizerHandler.Context context) {
        // Take and reset first, so the next DML statement in this transaction starts empty.
        Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.takePendingIds();
        if (opportunityIds.isEmpty()) {
            return;
        }
        System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
    }
}
