/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * The action's beforeUpdate method is called directly with in-memory triggerNew and
 * triggerOld lists. There is no DML and no SOQL, so the tests are fast and do not depend
 * on org data, validation rules or other automation.
 *
 * Note on fake Ids: TAF's TriggerTestUtility is annotated with @IsTest. Because TAF is
 * installed as a package, the org's own code cannot reference @IsTest classes inside that
 * package, so a call to TriggerTestUtility.getFakeId(...) would not compile here. This class
 * therefore has a private getFakeId helper. It builds the same kind of Id: the object's key
 * prefix followed by a zero-padded counter.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static Integer fakeIdCounter = 0;

    // Builds a syntactically valid Id for the SObjectType without touching the database.
    private static Id getFakeId(Schema.SObjectType sObjectType) {
        fakeIdCounter++;
        String keyPrefix = sObjectType.getDescribe().getKeyPrefix();
        String counter = String.valueOf(fakeIdCounter);
        return Id.valueOf(keyPrefix + '0'.repeat(12 - counter.length()) + counter);
    }

    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Name = 'Test Opportunity', Amount = amount);
    }

    // Runs the action through its TAF interface, the same way the framework calls it.
    private static void runBeforeUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        TriggerAction.BeforeUpdate action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
    }

    private static void assertSingleGuardError(Opportunity opp) {
        Assert.isTrue(opp.hasErrors(), 'Record should have been rejected.');
        List<Database.Error> errors = opp.getErrors();
        Assert.areEqual(1, errors.size(), 'Exactly one error should be added.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message should match the action constant.'
        );
    }

    private static void assertNoErrors(Opportunity opp) {
        Assert.isFalse(opp.hasErrors(), 'Record should not have been rejected.');
        Assert.areEqual(0, opp.getErrors().size(), 'No errors should be added.');
    }

