/**
 * Trigger Action (Trigger Actions Framework) that prevents two Contacts of the same Account
 * from sharing an email address (compared case-insensitively).
 *
 * - Contacts without an Account or without an Email are not checked.
 * - Before insert: every contact with an Account and an Email is checked.
 * - Before update: only contacts whose Account/Email combination changed are checked, so legacy
 *   duplicates do not block unrelated edits. A contact never conflicts with itself.
 * - Within one save, the first contact claiming an Account/Email combination wins; each later
 *   one is rejected with a record-level error (partial saves are supported).
 * - At most one SOQL query per execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>();
        if (triggerOld != null) {
            for (SObject oldRecord : triggerOld) {
                oldMap.put(oldRecord.Id, oldRecord);
            }
        }
        validate(triggerNew, oldMap);
    }

    private void validate(List<SObject> newRecords, Map<Id, SObject> oldMap) {
        if (newRecords == null || newRecords.isEmpty()) {
            return;
        }

        // Keys already in use: by existing records in the database, by unchanged records in this
        // save, and by records of this save accepted earlier in the list.
        Set<String> takenKeys = new Set<String>();
        // Ids of all records in this save; their database state is superseded by their new values.
        Set<Id> recordIdsInSave = new Set<Id>();

        List<Contact> contactsToCheck = new List<Contact>();
        List<String> keysToCheck = new List<String>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject record : newRecords) {
            Contact newContact = (Contact) record;
            if (newContact.Id != null) {
                recordIdsInSave.add(newContact.Id);
            }

            String newKey = buildKey(newContact.AccountId, newContact.Email);
            if (newKey == null) {
                continue; // no Account or no Email: not checked
            }

            Boolean mustCheck = true;
            if (oldMap != null) {
                Contact oldContact = (Contact) oldMap.get(newContact.Id);
                String oldKey = oldContact == null ? null : buildKey(oldContact.AccountId, oldContact.Email);
                mustCheck = !newKey.equals(oldKey);
            }

            if (mustCheck) {
                contactsToCheck.add(newContact);
                keysToCheck.add(newKey);
                accountIds.add(newContact.AccountId);
                emails.add(newContact.Email.toLowerCase());
            } else {
                // Unchanged contact in this save: it is an existing holder of its key.
                takenKeys.add(newKey);
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        for (Contact existing : new ExistingContactSelector().findByAccountsAndEmails(accountIds, emails, recordIdsInSave)) {
            String existingKey = buildKey(existing.AccountId, existing.Email);
            if (existingKey != null) {
                takenKeys.add(existingKey);
            }
        }

        for (Integer i = 0; i < contactsToCheck.size(); i++) {
            String key = keysToCheck[i];
            if (takenKeys.contains(key)) {
                contactsToCheck[i].addError(ERROR_MESSAGE);
            } else {
                takenKeys.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        if (accountId == null || String.isBlank(email)) {
            return null;
        }
        return String.valueOf(accountId) + '|' + email.trim().toLowerCase();
    }

    /**
     * Runs without sharing on purpose: the uniqueness rule must consider every Contact of the
     * Account, including those the running user cannot see. Only the minimal fields are read
     * and nothing is exposed to the user beyond the generic validation message.
     */
    private without sharing class ExistingContactSelector {
        List<Contact> findByAccountsAndEmails(Set<Id> accountIds, Set<String> emails, Set<Id> excludedIds) {
            // Text comparison in SOQL is case-insensitive, so lower-cased emails match any casing.
            return [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds AND Email IN :emails AND Id NOT IN :excludedIds
            ];
        }
    }
}
