/**
 * Trigger Actions Framework action that keeps Account.FB_Open_Case_Count__c equal to the
 * number of the account's Cases with IsClosed = false.
 *
 * Registered on Case for After Insert, After Update, After Delete and After Undelete.
 *
 * The count is always recalculated from the database (never incremented or decremented),
 * so it is correct for every path: insert (open or closed), close, reopen, reparent,
 * delete and undelete. It is also idempotent if the action runs more than once in a
 * transaction (for example after a workflow field update re-fires the update trigger).
 *
 * Limits per trigger execution: at most 2 SOQL queries and 1 DML statement.
 *
 * Runs without sharing on purpose: the roll-up must count all cases on the account,
 * not only those visible to the running user, and must be able to maintain the
 * system-owned count field even if the user cannot edit the account.
 */
public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
	public void afterInsert(List<SObject> triggerNew) {
		recalculate(collectAccountIds((List<Case>) triggerNew));
	}

	public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
		Map<Id, Case> oldCasesById = new Map<Id, Case>((List<Case>) triggerOld);
		Set<Id> accountIds = new Set<Id>();

		for (Case newCase : (List<Case>) triggerNew) {
			Case oldCase = oldCasesById.get(newCase.Id);
			if (oldCase == null) {
				continue;
			}
			Boolean accountChanged = newCase.AccountId != oldCase.AccountId;
			Boolean openStateChanged = newCase.IsClosed != oldCase.IsClosed || newCase.Status != oldCase.Status;

			if (accountChanged || openStateChanged) {
				if (newCase.AccountId != null) {
					accountIds.add(newCase.AccountId);
				}
				if (oldCase.AccountId != null) {
					accountIds.add(oldCase.AccountId);
				}
			}
		}

		recalculate(accountIds);
	}

	public void afterDelete(List<SObject> triggerOld) {
		recalculate(collectAccountIds((List<Case>) triggerOld));
	}

	public void afterUndelete(List<SObject> triggerNew) {
		recalculate(collectAccountIds((List<Case>) triggerNew));
	}

	private static Set<Id> collectAccountIds(List<Case> cases) {
		Set<Id> accountIds = new Set<Id>();
		for (Case c : cases) {
			if (c.AccountId != null) {
				accountIds.add(c.AccountId);
			}
		}
		return accountIds;
	}

	private static void recalculate(Set<Id> accountIds) {
		accountIds.remove(null);
		if (accountIds.isEmpty()) {
			return;
		}

		// Query 1: lock the affected accounts before counting so concurrent transactions on the
		// same account serialize and cannot write a stale count. Also skips accounts that no
		// longer exist.
		Map<Id, Account> accountsById = new Map<Id, Account>(
			[
				SELECT Id, FB_Open_Case_Count__c
				FROM Account
				WHERE Id IN :accountIds
				FOR UPDATE
			]
		);
		if (accountsById.isEmpty()) {
			return;
		}

		// Query 2: count open cases per account. Deleted (recycle bin) cases are excluded
		// automatically; undeleted cases are included again.
		Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
		for (AggregateResult result : [
			SELECT AccountId accountId, COUNT(Id) openCount
			FROM Case
			WHERE AccountId IN :accountsById.keySet() AND IsClosed = FALSE
			GROUP BY AccountId
		]) {
			openCountByAccountId.put((Id) result.get('accountId'), (Integer) result.get('openCount'));
		}

		List<Account> accountsToUpdate = new List<Account>();
		for (Account acc : accountsById.values()) {
			Integer openCount = openCountByAccountId.containsKey(acc.Id) ? openCountByAccountId.get(acc.Id) : 0;
			// Null-safe: a blank value compared with 0 counts as a change, so it is set to 0.
			if (acc.FB_Open_Case_Count__c != openCount) {
				accountsToUpdate.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = openCount));
			}
		}

		// Single DML. Errors are allowed to propagate so the case operation rolls back
		// rather than leaving the count out of sync.
		if (!accountsToUpdate.isEmpty()) {
			update accountsToUpdate;
		}
	}
}
