/**
 * Trigger Action (after update, Opportunity):
 * creates a completed "Amount changed" Task on every opportunity whose Amount changed.
 *
 * Recursion: TA_Opportunity_RoundAmount (Order 20) updates the same opportunities again in the
 * same transaction, which re-runs this action. That rounding is a consequence of the user's
 * change, so each opportunity is audited at most once per transaction. Ids that already got
 * an audit task in this transaction are kept in a static set and skipped afterwards.
 * Only opportunities that actually received a task are added to the set. An earlier update
 * without an Amount change therefore never suppresses a later real change.
 *
 * Bulk: one Task insert per trigger execution, regardless of batch size.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    @TestVisible
    private static final String TASK_SUBJECT = 'Amount changed';
    @TestVisible
    private static final String TASK_STATUS = 'Completed';

    // Opportunities that already received an audit task in the current transaction.
    @TestVisible
    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);

        List<Task> tasks = new List<Task>();
        Set<Id> newlyAudited = new Set<Id>();

        for (Opportunity opp : triggerNew) {
            if (auditedOpportunityIds.contains(opp.Id)) {
                continue; // already audited in this transaction (e.g. rounding re-update)
            }
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp == null || opp.Amount == oldOpp.Amount) {
                continue; // Amount unchanged: no task
            }
            tasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = opp.Id,
                    Status = TASK_STATUS
                )
            );
            newlyAudited.add(opp.Id);
        }

        if (tasks.isEmpty()) {
            return;
        }

        insert tasks;
        auditedOpportunityIds.addAll(newlyAudited);
    }
}
