/**
 * Shared query results for Contact trigger actions (Trigger Actions Framework
 * "avoid repeated queries" pattern).
 *
 * The inner Service class is registered as the first before insert action and
 * (re)loads the parent accounts on every trigger execution. Subsequent actions
 * read them from TA_Contact_Queries.getInstance().accountsById instead of
 * querying Accounts themselves.
 */
public with sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent accounts of the contacts in the current trigger execution.
     * Fields the running user cannot read are stripped from the records, so
     * consumers should read values via getPopulatedFieldsAsMap() or
     * getAccountValue().
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Returns the value of the given Account field if it was queried, is
     * readable by the running user and is not null; otherwise null.
     */
    public static Object getAccountValue(Account account, String fieldName) {
        if (account == null) {
            return null;
        }
        return account.getPopulatedFieldsAsMap().get(fieldName);
    }

    /**
     * Trigger action that loads the parent accounts once per trigger execution.
     */
    public with sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().accountsById = loadAccounts(triggerNew);
        }

        private Map<Id, Account> loadAccounts(List<SObject> triggerNew) {
            Map<Id, Account> result = new Map<Id, Account>();
            Set<Id> accountIds = new Set<Id>();
            for (SObject record : triggerNew) {
                Id accountId = ((Contact) record).AccountId;
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }
            if (accountIds.isEmpty()) {
                return result;
            }

            List<Account> accounts = [
                SELECT
                    Id,
                    BillingStreet,
                    BillingCity,
                    BillingPostalCode,
                    BillingCountry,
                    AccountSource
                FROM Account
                WHERE Id IN :accountIds
            ];

            SObjectAccessDecision decision = Security.stripInaccessible(
                AccessType.READABLE,
                accounts
            );
            for (SObject record : decision.getRecords()) {
                Account account = (Account) record;
                result.put(account.Id, account);
            }
            return result;
        }
    }
}
