/**
 * Before insert: a new contact with an Account and a completely blank mailing
 * address (street, city, postal code and country) inherits the account's
 * billing address. Uses accounts loaded by TA_Contact_Queries.Service.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;
            if (contact.AccountId == null || !hasBlankMailingAddress(contact)) {
                continue;
            }
            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            contact.MailingStreet = (String) TA_Contact_Queries.getAccountValue(account, 'BillingStreet');
            contact.MailingCity = (String) TA_Contact_Queries.getAccountValue(account, 'BillingCity');
            contact.MailingPostalCode = (String) TA_Contact_Queries.getAccountValue(account, 'BillingPostalCode');
            contact.MailingCountry = (String) TA_Contact_Queries.getAccountValue(account, 'BillingCountry');
        }
    }

    private static Boolean hasBlankMailingAddress(Contact contact) {
        return String.isBlank(contact.MailingStreet) &&
            String.isBlank(contact.MailingCity) &&
            String.isBlank(contact.MailingPostalCode) &&
            String.isBlank(contact.MailingCountry);
    }
}
