/**
 * Before insert: a new contact with an Account and a blank LeadSource gets the
 * account's AccountSource. Uses accounts loaded by TA_Contact_Queries.Service.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;
            if (contact.AccountId == null || String.isNotBlank(contact.LeadSource)) {
                continue;
            }
            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            String accountSource = (String) TA_Contact_Queries.getAccountValue(account, 'AccountSource');
            if (String.isNotBlank(accountSource)) {
                contact.LeadSource = accountSource;
            }
        }
    }
}
